,\n      ACT: 0.82, ACC: 1.00, ACA: 0.90, ACG: 0.38,\n      GCT: 0.79, GCC: 1.00, GCA: 0.73, GCG: 0.29,\n      TAT: 0.87, TAC: 1.00, CAT: 0.83, CAC: 1.00, CAA: 0.51, CAG: 1.00,\n      AAT: 0.88, AAC: 1.00, AAA: 0.86, AAG: 1.00, GAT: 0.93, GAC: 1.00,\n      GAA: 0.84, GAG: 1.00, TGT: 0.87, TGC: 1.00, TGG: 1.00,\n      CGT: 0.48, CGC: 0.63, CGA: 0.31, CGG: 1.00, AGA: 0.62, AGG: 0.65,\n      GGT: 0.62, GGC: 0.83, GGA: 1.00, GGG: 0.79\n    },\n    yeast: {\n      TTT: 0.60, TTC: 1.00, TTA: 0.29, TTG: 1.00, CTT: 0.13, CTC: 0.06, CTA: 0.14, CTG: 0.11,\n      ATT: 0.99, ATC: 1.00, ATA: 0.39, ATG: 1.00,\n      GTT: 1.00, GTC: 0.62, GTA: 0.44, GTG: 0.28,\n      TCT: 1.00, TCC: 0.74, TCA: 0.51, TCG: 0.15, AGT: 0.51, AGC: 0.33,\n      CCT: 1.00, CCC: 0.30, CCA: 0.79, CCG: 0.09,\n      ACT: 1.00, ACC: 0.79, ACA: 0.62, ACG: 0.26,\n      GCT: 1.00, GCC: 0.52, GCA: 0.71, GCG: 0.19,\n      TAT: 0.87, TAC: 1.00, CAT: 0.73, CAC: 1.00, CAA: 1.00, CAG: 0.31,\n      AAT: 1.00, AAC: 0.83, AAA: 1.00, AAG: 0.58, GAT: 1.00, GAC: 0.72,\n      GAA: 1.00, GAG: 0.45, TGT: 1.00, TGC: 0.63, TGG: 1.00,\n      CGT: 0.14, CGC: 0.06, CGA: 0.07, CGG: 0.04, AGA: 1.00, AGG: 0.66,\n      GGT: 1.00, GGC: 0.39, GGA: 0.31, GGG: 0.24\n    }\n  };\n  var DEGENERATE = { A: \'GCN\', C: \'TGY\', D: \'GAY\', E: \'GAR\', F: \'TTY\', G: \'GGN\',\n                     H: \'CAY\', I: \'ATH\', K: \'AAR\', L: \'YTN\', M: \'ATG\', N: \'AAY\',\n                     P: \'CCN\', Q: \'CAR\', R: \'MGN\', S: \'WSN\', T: \'ACN\', V: \'GTN\',\n                     W: \'TGG\', Y: \'TAY\', \'*\': \'TAR\' };\n\n  var ALL_CODONS = Object.keys(CODON_W.ecoli);\n  var PREFERRED = {}, PREFERRED_STOP = {};\n  function buildPreferred(key) {\n    var out = {}, best = {};\n    var table = CODON_W[key] || CODON_W.ecoli;\n    for (var i = 0; i < ALL_CODONS.length; i++) {\n      var cod = ALL_CODONS[i], aa = aaOf(cod);\n      if (!aa || aa === \'*\') continue;\n      var w = table[cod];\n      if (w === undefined) continue;\n      if (best[aa] === undefined || w > best[aa]) { best[aa] = w; out[aa] = cod; }\n    }\n    // the preferred stop codon is TAA in bacteria, TGA in eukaryotes\n    out[\'*\'] = key === \'ecoli\' ? \'TAA\' : \'TGA\';\n    return out;\n  }\n  var PREF = { ecoli: buildPreferred(\'ecoli\'), human: buildPreferred(\'human\'), yeast: buildPreferred(\'yeast\') };\n  function records(raw) {\n    var lines = String(raw || \'\').split(/\\r?\\n/), out = [], cur = null;\n    for (var i = 0; i < lines.length; i++) {\n      var line = lines[i].trim();\n      if (!line) continue;\n      if (line.charAt(0) === \'>\') {\n        cur = { name: line.slice(1).trim() || (\'sequence \' + (out.length + 1)), seq: \'\' };\n        out.push(cur);\n      } else {\n        if (!cur) { cur = { name: \'sequence 1\', seq: \'\' }; out.push(cur); }\n        cur.seq += line.replace(/[^A-Za-z]/g, \'\');\n      }\n    }\n    return out;\n  }\n  omni.onResult([\'proteins\', \'host\', \'stop\'], function (ctx) {\n    var recs = records(ctx.getRawInput(\'proteins\'));\n    var mode = resolve(ctx.getRawInput(\'host\'), { ecoli: \'ecoli\', human: \'human\', yeast: \'yeast\', degenerate: \'degenerate\' }, \'ecoli\');\n    var addStop = /true|yes|1/i.test(String(ctx.getRawInput(\'stop\') || \'\'));\n    if (!recs.length) {\n      ctx.addHtml(block(\'Reverse translation\', \'—\', \'Paste at least one protein sequence.\'));\n      ctx.exportValue(\'sequences\', 0); ctx.exportValue(\'residues\', 0); ctx.exportValue(\'gc\', 0);\n      return;\n    }\n    var html = \'\', done = 0, residues = 0, gc = 0, at = 0, problems = [];\n    for (var r = 0; r < recs.length && r < 20; r++) {\n      var pep = recs[r].seq.toUpperCase().replace(/[^A-Z*]/g, \'\');\n      if (!pep) { problems.push(recs[r].name + \': no residues\'); continue; }\n      var dna = \'\', i, unknown = [];\n      for (i = 0; i < pep.length; i++) {\n        var aa = pep.charAt(i);\n        if (aa === \'*\') { if (i === pep.length - 1 && addStop) dna += (PREF[mode] || PREF.ecoli)[\'*\']; continue; }\n        var cod;\n        if (mode === \'degenerate\') cod = DEGENERATE[aa];\n        else cod = (PREF[mode] || PREF.ecoli)[aa];\n        if (!cod) { unknown.push(aa + \'@\' + (i + 1)); continue; }\n        dna += cod;\n        residues++;\n      }\n      if (addStop && dna.length && pep.charAt(pep.length - 1) !== \'*\' && mode !== \'degenerate\') {\n        dna += (PREF[mode] || PREF.ecoli)[\'*\'];\n      }\n      for (i = 0; i < dna.length; i++) {\n        var ch = dna.charAt(i);\n        at++;\n        if (ch === \'G\' || ch === \'C\') gc++;\n      }\n      done++;\n      html += block(\'> \' + recs[r].name + \'  (\' + pep.length + \' aa → \' + dna.length + \' nt)\',\n        wrap(dna, 60), unknown.length ? \'Unreadable characters: \' + unknown.join(\', \') : \'\');\n    }\n    var pct = at ? gc / at * 100 : 0;\n    ctx.exportValue(\'sequences\', done);\n    ctx.exportValue(\'residues\', residues);\n    ctx.exportValue(\'gc\', Math.round(pct * 100) / 100);\n    var head = block(\'Reverse translation summary\',\n      \'Sequences   \' + done + \'\\nResidues    \' + residues + \'\\nCodon set   \' + mode\n      + \'\\nGC content  \' + pct.toFixed(1) + \' %\',\n      pct > 70 ? \'Above 70 % GC: expect synthesis difficulty and secondary structure.\'\n               : pct < 30 ? \'Below 30 % GC: check that the reading frame and host are what you meant.\'\n               : \'GC within the comfortable 30–70 % range.\');\n    ctx.addHtml(head + html + (problems.length ? block(\'Skipped\', problems.join(\'\\n\')) : \'\'));\n  });', NULL, 0, 1, 1, '2026-10-29 14:08:51', '2026-10-29 14:08:51'),
(205, 'fuzzy-protein-search', 'biology', 'Fuzzy Protein Search Calculator', 'Fuzzy Protein Search Calculator', 'Fuzzy Protein Search Calculator — Formula & Results', 'A fuzzy protein search finds an approximate motif: X matches any residue, B, Z and J their ambiguous pairs. Free fuzzy protein search calculator: enter your v', 'A fuzzy protein search finds an approximate motif: X matches any residue, B, Z and J their ambiguous pairs. It returns matches found, fewest mismatches in a hit and residues searched, and the panel shows all of them at once.\n\nEvery hit is reported with its position, its mass and how many positions it missed — the quick way to find a motif in a protein whose exact sequence you are not sure of. Press Calculate and the results appear in the grey boxes; after the first press they keep up with every edit, so there is no page to reload. Units are stated on every box and in every result, so a figure copied out of a protocol, a datasheet or a chart can be entered without converting it first.', '[{\"title\":\"The formula behind the Fuzzy Protein Search\",\"html\":\"<p>a window of length |P| matches when the number of positions where P[i] does not cover S[i] is ≤ the allowed mismatches</p>\\n<figure class=\\\"calc-figure\\\"><img src=\\\"/uploads/biology/fuzzy-protein-search.svg\\\" width=\\\"720\\\" height=\\\"300\\\" loading=\\\"lazy\\\" alt=\\\"Animated diagram: Fuzzy Protein Search Calculator — Hits for a six-residue motif at three mismatch allowances\\\" title=\\\"Fuzzy Protein Search Calculator\\\"><figcaption>Hits for a six-residue motif at three mismatch allowances</figcaption></figure>\\n<table><caption>The symbols in the formula</caption><thead><tr><th>Symbol</th><th>What it stands for</th><th>Unit</th></tr></thead><tbody><tr><td><code>S</code></td><td>the protein sequence</td><td>residues</td></tr><tr><td><code>P</code></td><td>the pattern</td><td>residues</td></tr><tr><td><code>X, B, Z, J</code></td><td>any residue; Asp/Asn; Glu/Gln; Ile/Leu</td><td>—</td></tr></tbody></table>\"},{\"title\":\"How do I use the Fuzzy Protein Search?\",\"html\":\"<p>Every input sits in the same order the formula is written, so the page reads like the equation.</p>\\n<ol><li>Paste the protein and the motif. Case does not matter.</li><li>Allow a mismatch or two if the sequence comes from a different isoform or a related species.</li><li>Read the positions and the reported masses: the mass tells you at a glance whether the hit is the peptide you expect or an unrelated stretch.</li></ol>\"},{\"title\":\"A worked example\",\"html\":\"<p>Take the default values the page opens with: mismatches allowed of <strong>0</strong>.</p>\\n<p>Those numbers come from the same solver the page runs in your browser, not from an illustration, so typing different inputs moves the answer exactly as the arithmetic says.</p>\"},{\"title\":\"What does the result mean?\",\"html\":\"<p>The number on its own is not a judgement. These are the bands most often used when the result is quoted in a paper, a report or a label:</p>\\n<table><caption>How to read the result</caption><thead><tr><th>Result</th><th>Band</th><th>What it means</th></tr></thead><tbody><tr><td>0 mismatches</td><td><strong>Exact motif</strong></td><td>the pattern is present as written</td></tr><tr><td>1 mismatch</td><td><strong>Conservative hit</strong></td><td>usually a point mutation or a species difference</td></tr><tr><td>2+ mismatches</td><td><strong>Loose hit</strong></td><td>raise the allowance only if you expect divergence</td></tr></tbody></table>\\n<ul><li><p>X matches any residue, so a pattern full of X matches almost anywhere — count the X positions before trusting a hit.</p></li><li><p>The search is a sliding window over the forward sequence only; report both strands only makes sense for DNA, and this page is for protein.</p></li><li><p>Masses are average residue masses plus one water, the same convention as a peptide mass calculator, so they will be a few hundredths off a monoisotopic mass.</p></li><li><p>Positions are 1-based, the convention in protein databases.</p></li></ul>\"},{\"title\":\"What are the common mistakes?\",\"html\":\"<p>These are the errors that account for almost every wrong answer people bring to this calculator:</p><ul><li>Searching a nucleotide sequence with a protein pattern — every window will look like noise.</li><li>Treating B and Z as literal letters; they are ambiguity codes for Asp/Asn and Glu/Gln.</li><li>Allowing three mismatches on a six-residue pattern, which matches everything.</li><li>Comparing a hit\'s average mass with a monoisotopic mass from a mass spectrometer and expecting them to agree to the last decimal.</li></ul>\"},{\"title\":\"Calculators that go with this one\",\"html\":\"<p>This tool answers one step of the question. The neighbouring steps have their own pages:</p><p><a href=\\\"/biology/dna-pattern-finder\\\">DNA pattern finder</a>. <a href=\\\"/biology/protein-molecular-weight\\\">Protein molecular weight</a>. <a href=\\\"/biology/amino-acid-composition\\\">Amino-acid composition</a>. <a href=\\\"/biology/protein-gravy-calculator\\\">GRAVY</a>.</p>\"}]', '[{\"q\":\"What does a fuzzy search do that an exact search does not?\",\"a\":\"It lets a pattern match when a few positions differ, and it understands the IUPAC ambiguity letters (B, Z, J, X) that protein databases use.\"},{\"q\":\"Why do I get a hit in a protein that should not contain the motif?\",\"a\":\"Because you allowed mismatches — check the mismatch count on the hit. With a short pattern and two allowed mismatches, random matches are common.\"},{\"q\":\"Are the masses monoisotopic or average?\",\"a\":\"Average, using the standard residue masses plus H₂O for the intact peptide. For a mass spectrometry match, compare the monoisotopic mass instead.\"},{\"q\":\"Can I search several patterns at once?\",\"a\":\"Run them one after another; the page reports every window of the one pattern you paste.\"},{\"q\":\"What does the Fuzzy Protein Search actually calculate?\",\"a\":\"It returns matches found, fewest mismatches in a hit and residues searched. Each one is derived by the formula on this page, so you can check any figure by hand.\"},{\"q\":\"Do I have to fill in every box?\",\"a\":\"Fill in the ones you know. The result boxes are computed from them, so you never enter a value the formula can derive — and if you change an input, every result updates with it.\"}]', '[{\"key\":\"protein\",\"label\":\"Protein sequence\",\"type\":\"text\",\"default\":\"MKWVTFISLLFLFSSAYSRGVFRRDAHKSEVAHRFKDLGEENFKALVLIAFAQYLQQCPFEDHVKLVNEVTEFAKTCVADESAENCDKS\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Paste the protein; FASTA headers and non-letter characters are ignored\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":false},{\"key\":\"pattern\",\"label\":\"Pattern to find\",\"type\":\"text\",\"default\":\"TCXAD\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Amino-acid letters, X for any residue, B = D/N, Z = E/Q, J = I/L\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":false},{\"key\":\"mismatch\",\"label\":\"Mismatches allowed\",\"type\":\"number\",\"default\":\"0\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"0 = exact, but X still matches any residue\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":false},{\"key\":\"hits\",\"label\":\"Matches found\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":true},{\"key\":\"best\",\"label\":\"Fewest mismatches in a hit\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":true},{\"key\":\"total\",\"label\":\"Residues searched\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":true}]', '[]', '{\"path\":\"/biology/fuzzy-protein-search\",\"slug\":\"fuzzy-protein-search\",\"cat\":\"biology\",\"name\":\"Fuzzy Protein Search Calculator\",\"title\":\"Fuzzy Protein Search Calculator — Formula & Results\",\"desc\":\"A fuzzy protein search finds an approximate motif: X matches any residue, B, Z and J their ambiguous pairs. Free fuzzy protein search calculator: enter your v\",\"authors\":[],\"reviewers\":[],\"updated\":\"2026-10-29\",\"rate\":0,\"groups\":[{\"uid\":\"custom-fuzzy-protein-search\",\"title\":\"\",\"desc\":\"\",\"m\":[[\"FR2\",[[{\"t\":\"v\",\"n\":\"protein\",\"l\":\"Protein sequence\",\"h\":\"Paste the protein; FASTA headers and non-letter characters are ignored\",\"vt\":\"text\"},{\"t\":\"v\",\"n\":\"pattern\",\"l\":\"Pattern to find\",\"h\":\"Amino-acid letters, X for any residue, B = D/N, Z = E/Q, J = I/L\",\"vt\":\"text\"},{\"t\":\"v\",\"n\":\"mismatch\",\"l\":\"Mismatches allowed\",\"h\":\"0 = exact, but X still matches any residue\",\"vt\":\"numerical\"}],[{\"t\":\"v\",\"n\":\"hits\",\"l\":\"Matches found\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"best\",\"l\":\"Fewest mismatches in a hit\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"total\",\"l\":\"Residues searched\",\"oo\":1,\"vt\":\"numerical\"}]]]]}],\"vars\":{\"protein\":{\"type\":\"text\",\"rnd\":null,\"dfl\":[{\"v\":\"MKWVTFISLLFLFSSAYSRGVFRRDAHKSEVAHRFKDLGEENFKALVLIAFAQYLQQCPFEDHVKLVNEVTEFAKTCVADESAENCDKS\",\"c\":null}]},\"pattern\":{\"type\":\"text\",\"rnd\":null,\"dfl\":[{\"v\":\"TCXAD\",\"c\":null}]},\"mismatch\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"0\",\"c\":null}]},\"hits\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"best\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"total\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]}},\"datasets\":[],\"eq\":[],\"js\":\"function cleanSeq(raw, kind) {\\n    var s = String(raw || \'\').replace(/^>.*$/gm, \'\');\\n    s = s.replace(/[^A-Za-z]/g, \'\');\\n    return kind === \'protein\' ? s.toUpperCase() : s.toUpperCase().replace(/U/g, \'T\');\\n  }\\n  function wrap(s, width) {\\n    width = width || 60;\\n    var out = [];\\n    for (var i = 0; i < s.length; i += width) out.push(s.slice(i, i + width));\\n    return out.join(\'\\\\n\');\\n  }\\n  function esc(s) {\\n    return String(s).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\');\\n  }\\n  function block(title, body, note) {\\n    return \'<div class=\\\"calc-script-block\\\"><h3>\' + esc(title) + \'</h3><pre>\' + esc(body) + \'</pre>\'\\n      + (note ? \'<p class=\\\"calc-script-note\\\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\\n  }\\n  function table(title, head, rows, note) {\\n    var h = \'<tr>\' + head.map(function (c) { return \'<th>\' + esc(c) + \'</th>\'; }).join(\'\') + \'</tr>\';\\n    var b = rows.map(function (r) {\\n      return \'<tr>\' + r.map(function (c) { return \'<td>\' + esc(c) + \'</td>\'; }).join(\'\') + \'</tr>\';\\n    }).join(\'\');\\n    return \'<div class=\\\"calc-script-block\\\"><h3>\' + esc(title) + \'</h3>\'\\n      + \'<div class=\\\"calc-script-scroll\\\"><table class=\\\"calc-script-table\\\">\' + h + b + \'</table></div>\'\\n      + (note ? \'<p class=\\\"calc-script-note\\\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\\n  }\\n  // A select arrives here as the option *uid* the panel generated from the label,\\n  // not as its value, so resolve by normalised containment and take the longest\\n  // match (otherwise \\\"hindiii\\\" would be caught by a shorter key like \\\"hin\\\").\\n  function resolve(raw, map, fallback) {\\n    var n = String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\');\\n    if (Object.prototype.hasOwnProperty.call(map, raw)) return map[raw];\\n    var keys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });\\n    for (var i = 0; i < keys.length; i++) {\\n      var k = keys[i].toLowerCase().replace(/[^a-z0-9]/g, \'\');\\n      if (k && n.indexOf(k) >= 0) return map[keys[i]];\\n    }\\n    return fallback;\\n  }\\n  var BASES = \'TCAG\';\\n  var AA_ORDER = \'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG\';\\n  function aaOf(codon) {\\n    var i1 = BASES.indexOf(codon.charAt(0)), i2 = BASES.indexOf(codon.charAt(1)),\\n        i3 = BASES.indexOf(codon.charAt(2));\\n    if (i1 < 0 || i2 < 0 || i3 < 0) return null;\\n    return AA_ORDER.charAt(i1 * 16 + i2 * 4 + i3);\\n  }\\n  var STOPS = { TAA: 1, TAG: 1, TGA: 1 };\\n  var MASS = { A: 71.0788, R: 156.1875, N: 114.1038, D: 115.0886, C: 103.1388,\\n               E: 129.1155, Q: 128.1307, G: 57.0519, H: 137.1411, I: 113.1594,\\n               L: 113.1594, K: 128.1741, M: 131.1926, F: 147.1766, P: 97.1167,\\n               S: 87.0782, T: 101.1051, W: 186.2132, Y: 163.1760, V: 99.1326 };\\n  function peptideMass(s) {\\n    var m = 0, n = 0;\\n    for (var i = 0; i < s.length; i++) {\\n      var x = MASS[s.charAt(i)];\\n      if (x) { m += x; n++; }\\n    }\\n    return n ? m + 18.01524 : 0;\\n  }\\n\\n  // What each ambiguity code will accept.\\n  var COVERS = {\\n    B: \'DN\', Z: \'EQ\', J: \'IL\', X: \'ACDEFGHIKLMNPQRSTVWY\',\\n    A: \'A\', C: \'C\', D: \'D\', E: \'E\', F: \'F\', G: \'G\', H: \'H\', I: \'I\', K: \'K\', L: \'L\',\\n    M: \'M\', N: \'N\', P: \'P\', Q: \'Q\', R: \'R\', S: \'S\', T: \'T\', V: \'V\', W: \'W\', Y: \'Y\'\\n  };\\n  omni.onResult([\'protein\', \'pattern\', \'mismatch\'], function (ctx) {\\n    var seq = cleanSeq(ctx.getRawInput(\'protein\'), \'protein\');\\n    var pat = cleanSeq(ctx.getRawInput(\'pattern\'), \'protein\');\\n    var allowed = Math.max(0, Math.min(10, Math.round(Number(ctx.getRawInput(\'mismatch\')) || 0)));\\n    if (!seq.length || !pat.length) {\\n      ctx.addHtml(block(\'Fuzzy protein search\', \'—\', \'Paste both a protein and a pattern.\'));\\n      ctx.exportValue(\'hits\', 0); ctx.exportValue(\'best\', 0); ctx.exportValue(\'total\', 0);\\n      return;\\n    }\\n    var bad = [];\\n    for (var q = 0; q < pat.length; q++) if (!COVERS[pat.charAt(q)]) bad.push(pat.charAt(q));\\n    if (bad.length) {\\n      ctx.addHtml(block(\'Fuzzy protein search\', \'—\',\\n        \'The pattern contains characters that are not amino acids: \' + bad.join(\' \')));\\n      ctx.exportValue(\'hits\', 0); ctx.exportValue(\'best\', 0); ctx.exportValue(\'total\', seq.length);\\n      return;\\n    }\\n    var rows = [], hits = 0, best = null, m, n;\\n    var wild = 0;\\n    for (var w = 0; w < pat.length; w++) if (pat.charAt(w) === \'X\') wild++;\\n    for (var i = 0; i + pat.length <= seq.length; i++) {\\n      m = 0;\\n      for (var j = 0; j < pat.length; j++) {\\n        var set = COVERS[pat.charAt(j)] || \'X\';\\n        if (set.indexOf(seq.charAt(i + j)) < 0) m++;\\n        if (m > allowed) break;\\n      }\\n      if (m <= allowed) {\\n        hits++;\\n        if (best === null || m < best) best = m;\\n        if (rows.length < 15) {\\n          var piece = seq.substr(i, pat.length);\\n          rows.push([String(i + 1), piece, String(m), peptideMass(piece).toFixed(2)]);\\n        }\\n      }\\n    }\\n    ctx.exportValue(\'hits\', hits);\\n    ctx.exportValue(\'best\', best === null ? 0 : best);\\n    ctx.exportValue(\'total\', seq.length);\\n    var head = block(\'Fuzzy protein search\',\\n      \'Pattern            \' + pat + \'\\\\nLength searched    \' + seq.length + \' residues\\\\n\'\\n      + \'Mismatches allowed \' + allowed + \'\\\\nMatches found      \' + hits,\\n      wild ? wild + \' wildcard position(s) in the pattern — a pattern of all X matches everywhere.\'\\n                   : \'Positions are 1-based.\');\\n    var html = head + table(\'Hits\', [\'Position\', \'Match\', \'Mismatches\', \'Mass (Da)\'],\\n      rows.length ? rows : [[\'—\', \'no match\', \'—\', \'—\']],\\n      rows.length > 15 ? \'First 15 shown.\' : \'\');\\n    ctx.addHtml(html);\\n  });\",\"needsJs\":false}', 'dna', '', 'published', 0, 1000, 0, 'function cleanSeq(raw, kind) {\n    var s = String(raw || \'\').replace(/^>.*$/gm, \'\');\n    s = s.replace(/[^A-Za-z]/g, \'\');\n    return kind === \'protein\' ? s.toUpperCase() : s.toUpperCase().replace(/U/g, \'T\');\n  }\n  function wrap(s, width) {\n    width = width || 60;\n    var out = [];\n    for (var i = 0; i < s.length; i += width) out.push(s.slice(i, i + width));\n    return out.join(\'\\n\');\n  }\n  function esc(s) {\n    return String(s).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\');\n  }\n  function block(title, body, note) {\n    return \'<div class=\"calc-script-block\"><h3>\' + esc(title) + \'</h3><pre>\' + esc(body) + \'</pre>\'\n      + (note ? \'<p class=\"calc-script-note\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\n  }\n  function table(title, head, rows, note) {\n    var h = \'<tr>\' + head.map(function (c) { return \'<th>\' + esc(c) + \'</th>\'; }).join(\'\') + \'</tr>\';\n    var b = rows.map(function (r) {\n      return \'<tr>\' + r.map(function (c) { return \'<td>\' + esc(c) + \'</td>\'; }).join(\'\') + \'</tr>\';\n    }).join(\'\');\n    return \'<div class=\"calc-script-block\"><h3>\' + esc(title) + \'</h3>\'\n      + \'<div class=\"calc-script-scroll\"><table class=\"calc-script-table\">\' + h + b + \'</table></div>\'\n      + (note ? \'<p class=\"calc-script-note\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\n  }\n  // A select arrives here as the option *uid* the panel generated from the label,\n  // not as its value, so resolve by normalised containment and take the longest\n  // match (otherwise \"hindiii\" would be caught by a shorter key like \"hin\").\n  function resolve(raw, map, fallback) {\n    var n = String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\');\n    if (Object.prototype.hasOwnProperty.call(map, raw)) return map[raw];\n    var keys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });\n    for (var i = 0; i < keys.length; i++) {\n      var k = keys[i].toLowerCase().replace(/[^a-z0-9]/g, \'\');\n      if (k && n.indexOf(k) >= 0) return map[keys[i]];\n    }\n    return fallback;\n  }\n  var BASES = \'TCAG\';\n  var AA_ORDER = \'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG\';\n  function aaOf(codon) {\n    var i1 = BASES.indexOf(codon.charAt(0)), i2 = BASES.indexOf(codon.charAt(1)),\n        i3 = BASES.indexOf(codon.charAt(2));\n    if (i1 < 0 || i2 < 0 || i3 < 0) return null;\n    return AA_ORDER.charAt(i1 * 16 + i2 * 4 + i3);\n  }\n  var STOPS = { TAA: 1, TAG: 1, TGA: 1 };\n  var MASS = { A: 71.0788, R: 156.1875, N: 114.1038, D: 115.0886, C: 103.1388,\n               E: 129.1155, Q: 128.1307, G: 57.0519, H: 137.1411, I: 113.1594,\n               L: 113.1594, K: 128.1741, M: 131.1926, F: 147.1766, P: 97.1167,\n               S: 87.0782, T: 101.1051, W: 186.2132, Y: 163.1760, V: 99.1326 };\n  function peptideMass(s) {\n    var m = 0, n = 0;\n    for (var i = 0; i < s.length; i++) {\n      var x = MASS[s.charAt(i)];\n      if (x) { m += x; n++; }\n    }\n    return n ? m + 18.01524 : 0;\n  }\n\n  // What each ambiguity code will accept.\n  var COVERS = {\n    B: \'DN\', Z: \'EQ\', J: \'IL\', X: \'ACDEFGHIKLMNPQRSTVWY\',\n    A: \'A\', C: \'C\', D: \'D\', E: \'E\', F: \'F\', G: \'G\', H: \'H\', I: \'I\', K: \'K\', L: \'L\',\n    M: \'M\', N: \'N\', P: \'P\', Q: \'Q\', R: \'R\', S: \'S\', T: \'T\', V: \'V\', W: \'W\', Y: \'Y\'\n  };\n  omni.onResult([\'protein\', \'pattern\', \'mismatch\'], function (ctx) {\n    var seq = cleanSeq(ctx.getRawInput(\'protein\'), \'protein\');\n    var pat = cleanSeq(ctx.getRawInput(\'pattern\'), \'protein\');\n    var allowed = Math.max(0, Math.min(10, Math.round(Number(ctx.getRawInput(\'mismatch\')) || 0)));\n    if (!seq.length || !pat.length) {\n      ctx.addHtml(block(\'Fuzzy protein search\', \'—\', \'Paste both a protein and a pattern.\'));\n      ctx.exportValue(\'hits\', 0); ctx.exportValue(\'best\', 0); ctx.exportValue(\'total\', 0);\n      return;\n    }\n    var bad = [];\n    for (var q = 0; q < pat.length; q++) if (!COVERS[pat.charAt(q)]) bad.push(pat.charAt(q));\n    if (bad.length) {\n      ctx.addHtml(block(\'Fuzzy protein search\', \'—\',\n        \'The pattern contains characters that are not amino acids: \' + bad.join(\' \')));\n      ctx.exportValue(\'hits\', 0); ctx.exportValue(\'best\', 0); ctx.exportValue(\'total\', seq.length);\n      return;\n    }\n    var rows = [], hits = 0, best = null, m, n;\n    var wild = 0;\n    for (var w = 0; w < pat.length; w++) if (pat.charAt(w) === \'X\') wild++;\n    for (var i = 0; i + pat.length <= seq.length; i++) {\n      m = 0;\n      for (var j = 0; j < pat.length; j++) {\n        var set = COVERS[pat.charAt(j)] || \'X\';\n        if (set.indexOf(seq.charAt(i + j)) < 0) m++;\n        if (m > allowed) break;\n      }\n      if (m <= allowed) {\n        hits++;\n        if (best === null || m < best) best = m;\n        if (rows.length < 15) {\n          var piece = seq.substr(i, pat.length);\n          rows.push([String(i + 1), piece, String(m), peptideMass(piece).toFixed(2)]);\n        }\n      }\n    }\n    ctx.exportValue(\'hits\', hits);\n    ctx.exportValue(\'best\', best === null ? 0 : best);\n    ctx.exportValue(\'total\', seq.length);\n    var head = block(\'Fuzzy protein search\',\n      \'Pattern            \' + pat + \'\\nLength searched    \' + seq.length + \' residues\\n\'\n      + \'Mismatches allowed \' + allowed + \'\\nMatches found      \' + hits,\n      wild ? wild + \' wildcard position(s) in the pattern — a pattern of all X matches everywhere.\'\n                   : \'Positions are 1-based.\');\n    var html = head + table(\'Hits\', [\'Position\', \'Match\', \'Mismatches\', \'Mass (Da)\'],\n      rows.length ? rows : [[\'—\', \'no match\', \'—\', \'—\']],\n      rows.length > 15 ? \'First 15 shown.\' : \'\');\n    ctx.addHtml(html);\n  });', NULL, 0, 1, 1, '2026-10-29 14:08:51', '2026-10-29 14:08:51'),
(206, 'random-sequence-generator', 'biology', 'Random Sequence Generator Calculator', 'Random Sequence Generator Calculator', 'Random Sequence Generator Calculator — Formula & Results', 'Generate a random DNA, RNA or protein sequence of any length with a target GC content, and get the same sequence back every time from the same seed. Free rand', 'Generate a random DNA, RNA or protein sequence of any length with a target GC content, and get the same sequence back every time from the same seed. It returns gc content of the output, and the panel shows all of them at once.\n\nIt is the negative control you need for a motif search, a composition baseline for a GC calculator, or a training example for a pipeline. Every result is derived from the boxes you fill in, so changing one input updates the whole panel at once. Units are stated on every box and in every result, so a figure copied out of a protocol, a datasheet or a chart can be entered without converting it first.', '[{\"title\":\"The formula behind the Random Sequence Generator\",\"html\":\"<p>each base is drawn from a seeded 32-bit generator, with G and C chosen with probability GC/2 each</p>\\n<figure class=\\\"calc-figure\\\"><img src=\\\"/uploads/biology/random-sequence-generator.svg\\\" width=\\\"720\\\" height=\\\"300\\\" loading=\\\"lazy\\\" alt=\\\"Animated diagram: Random Sequence Generator Calculator — Base composition of a 1 000-base draw at 50 % GC\\\" title=\\\"Random Sequence Generator Calculator\\\"><figcaption>Base composition of a 1 000-base draw at 50 % GC</figcaption></figure>\\n<table><caption>The symbols in the formula</caption><thead><tr><th>Symbol</th><th>What it stands for</th><th>Unit</th></tr></thead><tbody><tr><td><code>seed</code></td><td>the integer that fixes the pseudo-random stream</td><td>—</td></tr><tr><td><code>GC</code></td><td>target fraction of G + C</td><td>%</td></tr><tr><td><code>n</code></td><td>length of the sequence</td><td>bases</td></tr></tbody></table>\"},{\"title\":\"How do I use the Random Sequence Generator?\",\"html\":\"<p>The form asks only for what the formula needs — nothing is optional decoration.</p>\\n<ol><li>Choose the alphabet, the length and — for DNA or RNA — the GC content you want.</li><li>Keep the seed if you need the same sequence again, change it for a different draw.</li><li>Copy the output: it is wrapped at 60 columns and the seed is printed with it, so anyone can reproduce exactly what you used.</li></ol>\"},{\"title\":\"A worked example\",\"html\":\"<p>Take the default values the page opens with: length of <strong>1,000</strong> residues, target gc content of <strong>50</strong>%, seed of <strong>42</strong>, make the sequence start with atg of <strong>0</strong>.</p>\\n<p>The arithmetic is the page\'s own: change one box and the result moves by the amount the formula implies, which is the quickest way to convince yourself the tool is honest.</p>\"},{\"title\":\"What does the result mean?\",\"html\":\"<p>A raw figure only means something next to the bands it is normally judged against. Here is the scale that goes with this one:</p>\\n<table><caption>How to read the result</caption><thead><tr><th>Result</th><th>Band</th><th>What it means</th></tr></thead><tbody><tr><td>20 – 40 % GC</td><td><strong>AT-rich</strong></td><td>typical of a bacterial genome\'s variable regions and of some promoters</td></tr><tr><td>40 – 60 % GC</td><td><strong>Balanced</strong></td><td>the usual null model for a mammalian sequence</td></tr><tr><td>60 – 80 % GC</td><td><strong>GC-rich</strong></td><td>like a CpG island or a GC3-rich coding sequence</td></tr></tbody></table>\\n<ul><li><p>The random draw is deterministic from the seed: the same seed and length always give the same sequence, which is what makes a \'random\' control reproducible in a paper.</p></li><li><p>GC is applied as a target, so the achieved value wobbles around it by the binomial sampling error — for 1 000 bases at 50 %, expect about ±1.6 points.</p></li><li><p>A protein draw uses the 20 standard residues with equal probability, not the natural amino-acid frequencies; that is what you want for a shuffled control, and it is stated in the output rather than assumed.</p></li><li><p>Nothing here is cryptographically random. For keys or identifiers use a proper CSPRNG.</p></li></ul>\"},{\"title\":\"What are the common mistakes?\",\"html\":\"<p>The arithmetic is simple; the inputs are where things go wrong. The usual culprits:</p><ul><li>Using a random sequence as a statistical null without matching its GC content to the real sequence — composition dominates most motif statistics.</li><li>Assuming two different seeds give unrelated sequences: they do, but a short sequence can happen to look similar, which is the point of the test.</li><li>Generating a \'random\' protein with natural frequencies and calling it a shuffled control.</li><li>Losing the seed and then being unable to reproduce a figure.</li></ul>\"},{\"title\":\"Calculators that go with this one\",\"html\":\"<p>If you need the rest of the working, these cover the adjacent quantities:</p><p><a href=\\\"/biology/sequence-shuffler\\\">Sequence shuffler</a>. <a href=\\\"/biology/gc-content-calculator\\\">GC content</a>. <a href=\\\"/biology/dna-pattern-finder\\\">DNA pattern finder</a>. <a href=\\\"/biology/reverse-complement\\\">Reverse complement</a>.</p>\"}]', '[{\"q\":\"Is the sequence truly random?\",\"a\":\"It is pseudo-random and deterministic from the seed: statistically uniform, perfectly reproducible, and not suitable for anything security-related.\"},{\"q\":\"Why does the GC content not exactly match what I asked for?\",\"a\":\"Because each base is drawn independently, so the realised count fluctuates around the target — more bases means a smaller wobble. The page reports what it actually produced.\"},{\"q\":\"Can I regenerate the same sequence later?\",\"a\":\"Yes — keep the seed and the length. The output block prints the seed for exactly that reason.\"},{\"q\":\"Does the protein mode use natural amino-acid frequencies?\",\"a\":\"No. It draws the 20 residues uniformly, which is the right control for a shuffled sequence. Use a composition-matched generator if your null model needs natural frequencies.\"},{\"q\":\"What does the Random Sequence Generator actually calculate?\",\"a\":\"It returns gc content of the output. Each one is derived by the formula on this page, so you can check any figure by hand.\"},{\"q\":\"Do I have to fill in every box?\",\"a\":\"Fill in the ones you know. The result boxes are computed from them, so you never enter a value the formula can derive — and if you change an input, every result updates with it.\"}]', '[{\"key\":\"kind\",\"label\":\"Alphabet\",\"type\":\"select\",\"default\":\"dna-acgt\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[[\"dna-acgt\",\"DNA (ACGT)\",\"dna\"],[\"rna-acgu\",\"RNA (ACGU)\",\"rna\"],[\"protein-20-aa\",\"Protein (20 aa)\",\"protein\"]],\"output\":false},{\"key\":\"length\",\"label\":\"Length\",\"type\":\"number\",\"default\":\"1000\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"1 to 100 000\",\"prefix\":\"\",\"suffix\":\"residues\",\"options\":[],\"output\":false},{\"key\":\"gc\",\"label\":\"Target GC content\",\"type\":\"number\",\"default\":\"50\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"DNA and RNA only\",\"prefix\":\"\",\"suffix\":\"%\",\"options\":[],\"output\":false},{\"key\":\"seed\",\"label\":\"Seed\",\"type\":\"number\",\"default\":\"42\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Same seed, same sequence — any whole number\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":false},{\"key\":\"gc_actual\",\"label\":\"GC content of the output\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"%\",\"options\":[],\"output\":true},{\"key\":\"start\",\"label\":\"Make the sequence start with ATG\",\"type\":\"checkbox\",\"default\":\"0\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"DNA only — gives you a start codon\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":false}]', '[]', '{\"path\":\"/biology/random-sequence-generator\",\"slug\":\"random-sequence-generator\",\"cat\":\"biology\",\"name\":\"Random Sequence Generator Calculator\",\"title\":\"Random Sequence Generator Calculator — Formula & Results\",\"desc\":\"Generate a random DNA, RNA or protein sequence of any length with a target GC content, and get the same sequence back every time from the same seed. Free rand\",\"authors\":[],\"reviewers\":[],\"updated\":\"2026-10-29\",\"rate\":0,\"groups\":[{\"uid\":\"custom-random-sequence-generator\",\"title\":\"\",\"desc\":\"\",\"m\":[[\"FR2\",[[{\"t\":\"v\",\"n\":\"kind\",\"l\":\"Alphabet\",\"vt\":\"valueSelect\",\"ds\":\"ds-kind\",\"opts\":[[\"dna-acgt\",\"DNA (ACGT)\",\"dna\"],[\"rna-acgu\",\"RNA (ACGU)\",\"rna\"],[\"protein-20-aa\",\"Protein (20 aa)\",\"protein\"]]},{\"t\":\"v\",\"n\":\"length\",\"l\":\"Length\",\"h\":\"1 to 100 000\",\"suf\":\"residues\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"gc\",\"l\":\"Target GC content\",\"h\":\"DNA and RNA only\",\"suf\":\"%\",\"vt\":\"numerical\"}],[{\"t\":\"v\",\"n\":\"seed\",\"l\":\"Seed\",\"h\":\"Same seed, same sequence — any whole number\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"gc_actual\",\"l\":\"GC content of the output\",\"suf\":\"%\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"start\",\"l\":\"Make the sequence start with ATG\",\"h\":\"DNA only — gives you a start codon\",\"vt\":\"valueSelect\",\"ds\":\"ds-start\",\"opts\":[[\"yes\",\"Yes\",\"1\"],[\"no\",\"No\",\"0\"]]}]]]]}],\"vars\":{\"kind\":{\"type\":\"valueSelect\",\"rnd\":null,\"dfl\":[{\"v\":\"dna-acgt\",\"c\":null}],\"ds\":\"ds-kind\"},\"length\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"1000\",\"c\":null}]},\"gc\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"50\",\"c\":null}]},\"seed\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"42\",\"c\":null}]},\"gc_actual\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"start\":{\"type\":\"valueSelect\",\"rnd\":null,\"dfl\":[{\"v\":\"no\",\"c\":null}],\"ds\":\"ds-start\"}},\"datasets\":{\"ds-kind\":{\"name\":\"Alphabet\",\"uiType\":\"RADIO\",\"options\":[{\"uid\":\"dna-acgt\",\"label\":\"DNA (ACGT)\",\"value\":\"dna\"},{\"uid\":\"rna-acgu\",\"label\":\"RNA (ACGU)\",\"value\":\"rna\"},{\"uid\":\"protein-20-aa\",\"label\":\"Protein (20 aa)\",\"value\":\"protein\"}]},\"ds-start\":{\"name\":\"Make the sequence start with ATG\",\"uiType\":\"RADIO\",\"options\":[{\"uid\":\"yes\",\"label\":\"Yes\",\"value\":\"1\"},{\"uid\":\"no\",\"label\":\"No\",\"value\":\"0\"}]}},\"eq\":[],\"js\":\"function cleanSeq(raw, kind) {\\n    var s = String(raw || \'\').replace(/^>.*$/gm, \'\');\\n    s = s.replace(/[^A-Za-z]/g, \'\');\\n    return kind === \'protein\' ? s.toUpperCase() : s.toUpperCase().replace(/U/g, \'T\');\\n  }\\n  function wrap(s, width) {\\n    width = width || 60;\\n    var out = [];\\n    for (var i = 0; i < s.length; i += width) out.push(s.slice(i, i + width));\\n    return out.join(\'\\\\n\');\\n  }\\n  function esc(s) {\\n    return String(s).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\');\\n  }\\n  function block(title, body, note) {\\n    return \'<div class=\\\"calc-script-block\\\"><h3>\' + esc(title) + \'</h3><pre>\' + esc(body) + \'</pre>\'\\n      + (note ? \'<p class=\\\"calc-script-note\\\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\\n  }\\n  function table(title, head, rows, note) {\\n    var h = \'<tr>\' + head.map(function (c) { return \'<th>\' + esc(c) + \'</th>\'; }).join(\'\') + \'</tr>\';\\n    var b = rows.map(function (r) {\\n      return \'<tr>\' + r.map(function (c) { return \'<td>\' + esc(c) + \'</td>\'; }).join(\'\') + \'</tr>\';\\n    }).join(\'\');\\n    return \'<div class=\\\"calc-script-block\\\"><h3>\' + esc(title) + \'</h3>\'\\n      + \'<div class=\\\"calc-script-scroll\\\"><table class=\\\"calc-script-table\\\">\' + h + b + \'</table></div>\'\\n      + (note ? \'<p class=\\\"calc-script-note\\\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\\n  }\\n  // A select arrives here as the option *uid* the panel generated from the label,\\n  // not as its value, so resolve by normalised containment and take the longest\\n  // match (otherwise \\\"hindiii\\\" would be caught by a shorter key like \\\"hin\\\").\\n  function resolve(raw, map, fallback) {\\n    var n = String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\');\\n    if (Object.prototype.hasOwnProperty.call(map, raw)) return map[raw];\\n    var keys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });\\n    for (var i = 0; i < keys.length; i++) {\\n      var k = keys[i].toLowerCase().replace(/[^a-z0-9]/g, \'\');\\n      if (k && n.indexOf(k) >= 0) return map[keys[i]];\\n    }\\n    return fallback;\\n  }\\n  var BASES = \'TCAG\';\\n  var AA_ORDER = \'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG\';\\n  function aaOf(codon) {\\n    var i1 = BASES.indexOf(codon.charAt(0)), i2 = BASES.indexOf(codon.charAt(1)),\\n        i3 = BASES.indexOf(codon.charAt(2));\\n    if (i1 < 0 || i2 < 0 || i3 < 0) return null;\\n    return AA_ORDER.charAt(i1 * 16 + i2 * 4 + i3);\\n  }\\n  var STOPS = { TAA: 1, TAG: 1, TGA: 1 };\\n  var MASS = { A: 71.0788, R: 156.1875, N: 114.1038, D: 115.0886, C: 103.1388,\\n               E: 129.1155, Q: 128.1307, G: 57.0519, H: 137.1411, I: 113.1594,\\n               L: 113.1594, K: 128.1741, M: 131.1926, F: 147.1766, P: 97.1167,\\n               S: 87.0782, T: 101.1051, W: 186.2132, Y: 163.1760, V: 99.1326 };\\n  function peptideMass(s) {\\n    var m = 0, n = 0;\\n    for (var i = 0; i < s.length; i++) {\\n      var x = MASS[s.charAt(i)];\\n      if (x) { m += x; n++; }\\n    }\\n    return n ? m + 18.01524 : 0;\\n  }\\n\\n  function mulberry32(a) {\\n    return function () {\\n      a |= 0; a = (a + 0x6D2B79F5) | 0;\\n      var t = Math.imul(a ^ (a >>> 15), 1 | a);\\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\\n    };\\n  }\\n  omni.onResult([\'kind\', \'length\', \'gc\', \'seed\', \'start\'], function (ctx) {\\n    var kind = resolve(ctx.getRawInput(\'kind\'), { dna: \'dna\', rna: \'rna\', protein: \'protein\' }, \'dna\');\\n    var n = Math.round(Number(ctx.getRawInput(\'length\')) || 0);\\n    if (!(n > 0)) n = 0;\\n    n = Math.min(n, 100000);\\n    var gcTarget = Math.max(0, Math.min(100, Number(ctx.getRawInput(\'gc\')) || 0));\\n    var seed = Math.round(Number(ctx.getRawInput(\'seed\')) || 0);\\n    var start = /true|yes|1/i.test(String(ctx.getRawInput(\'start\') || \'\'));\\n    if (!n) {\\n      ctx.addHtml(block(\'Random sequence\', \'—\', \'Enter a length between 1 and 100 000.\'));\\n      ctx.exportValue(\'gc_actual\', 0);\\n      return;\\n    }\\n    var rnd = mulberry32(seed);\\n    var seq = \'\', counts = {}, i, ch;\\n    var seqAlpha = kind === \'protein\' ? \'ACDEFGHIKLMNPQRSTVWY\' : (kind === \'rna\' ? \'ACGU\' : \'ACGT\');\\n    var gcPair = kind === \'rna\' ? [\'G\', \'C\'] : [\'G\', \'C\'];\\n    for (i = 0; i < n; i++) {\\n      if (kind === \'protein\') ch = seqAlpha.charAt(Math.floor(rnd() * seqAlpha.length) % seqAlpha.length);\\n      else {\\n        var r = rnd() * 100;\\n        if (r < gcTarget / 2) ch = gcPair[0];\\n        else if (r < gcTarget) ch = gcPair[1];\\n        else ch = (rnd() < 0.5 ? \'A\' : (kind === \'rna\' ? \'U\' : \'T\'));\\n      }\\n      seq += ch;\\n      counts[ch] = (counts[ch] || 0) + 1;\\n    }\\n    if (kind !== \'protein\' && start && n >= 3) {\\n      seq = \'ATG\' + seq.slice(3);\\n      counts = {};\\n      for (i = 0; i < seq.length; i++) { ch = seq.charAt(i); counts[ch] = (counts[ch] || 0) + 1; }\\n    }\\n    var gcN = (counts.G || 0) + (counts.C || 0);\\n    var pct = kind === \'protein\' ? 0 : gcN / n * 100;\\n    ctx.exportValue(\'gc_actual\', Math.round(pct * 100) / 100);\\n    var rows = [];\\n    var keys = Object.keys(counts).sort();\\n    for (i = 0; i < keys.length; i++) {\\n      rows.push([keys[i], String(counts[keys[i]]), (counts[keys[i]] / n * 100).toFixed(2) + \' %\']);\\n    }\\n    var kindName = kind === \'protein\' ? \'protein\' : (kind === \'rna\' ? \'RNA\' : \'DNA\');\\n    var head = block(\'Random \' + kindName + \' sequence — seed \' + seed,\\n      \'Length      \' + n + \'\\\\nSeed        \' + seed\\n      + (kind === \'protein\' ? \'\\\\nAlphabet    20 standard residues, uniform\'\\n                            : \'\\\\nTarget GC   \' + gcTarget + \' %\\\\nRealised GC \' + pct.toFixed(2) + \' %\')\\n      + (start && kind !== \'protein\' ? \'\\\\nStart       ATG forced at position 1\' : \'\'),\\n      \'Reuse the seed and the length to get this exact sequence again.\');\\n    ctx.addHtml(head + block(\'Sequence\', wrap(seq, 60)) + table(\'Composition\', [\'Symbol\', \'Count\', \'Share\'], rows));\\n  });\",\"needsJs\":false}', 'dna', '', 'published', 0, 1000, 0, 'function cleanSeq(raw, kind) {\n    var s = String(raw || \'\').replace(/^>.*$/gm, \'\');\n    s = s.replace(/[^A-Za-z]/g, \'\');\n    return kind === \'protein\' ? s.toUpperCase() : s.toUpperCase().replace(/U/g, \'T\');\n  }\n  function wrap(s, width) {\n    width = width || 60;\n    var out = [];\n    for (var i = 0; i < s.length; i += width) out.push(s.slice(i, i + width));\n    return out.join(\'\\n\');\n  }\n  function esc(s) {\n    return String(s).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\');\n  }\n  function block(title, body, note) {\n    return \'<div class=\"calc-script-block\"><h3>\' + esc(title) + \'</h3><pre>\' + esc(body) + \'</pre>\'\n      + (note ? \'<p class=\"calc-script-note\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\n  }\n  function table(title, head, rows, note) {\n    var h = \'<tr>\' + head.map(function (c) { return \'<th>\' + esc(c) + \'</th>\'; }).join(\'\') + \'</tr>\';\n    var b = rows.map(function (r) {\n      return \'<tr>\' + r.map(function (c) { return \'<td>\' + esc(c) + \'</td>\'; }).join(\'\') + \'</tr>\';\n    }).join(\'\');\n    return \'<div class=\"calc-script-block\"><h3>\' + esc(title) + \'</h3>\'\n      + \'<div class=\"calc-script-scroll\"><table class=\"calc-script-table\">\' + h + b + \'</table></div>\'\n      + (note ? \'<p class=\"calc-script-note\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\n  }\n  // A select arrives here as the option *uid* the panel generated from the label,\n  // not as its value, so resolve by normalised containment and take the longest\n  // match (otherwise \"hindiii\" would be caught by a shorter key like \"hin\").\n  function resolve(raw, map, fallback) {\n    var n = String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\');\n    if (Object.prototype.hasOwnProperty.call(map, raw)) return map[raw];\n    var keys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });\n    for (var i = 0; i < keys.length; i++) {\n      var k = keys[i].toLowerCase().replace(/[^a-z0-9]/g, \'\');\n      if (k && n.indexOf(k) >= 0) return map[keys[i]];\n    }\n    return fallback;\n  }\n  var BASES = \'TCAG\';\n  var AA_ORDER = \'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG\';\n  function aaOf(codon) {\n    var i1 = BASES.indexOf(codon.charAt(0)), i2 = BASES.indexOf(codon.charAt(1)),\n        i3 = BASES.indexOf(codon.charAt(2));\n    if (i1 < 0 || i2 < 0 || i3 < 0) return null;\n    return AA_ORDER.charAt(i1 * 16 + i2 * 4 + i3);\n  }\n  var STOPS = { TAA: 1, TAG: 1, TGA: 1 };\n  var MASS = { A: 71.0788, R: 156.1875, N: 114.1038, D: 115.0886, C: 103.1388,\n               E: 129.1155, Q: 128.1307, G: 57.0519, H: 137.1411, I: 113.1594,\n               L: 113.1594, K: 128.1741, M: 131.1926, F: 147.1766, P: 97.1167,\n               S: 87.0782, T: 101.1051, W: 186.2132, Y: 163.1760, V: 99.1326 };\n  function peptideMass(s) {\n    var m = 0, n = 0;\n    for (var i = 0; i < s.length; i++) {\n      var x = MASS[s.charAt(i)];\n      if (x) { m += x; n++; }\n    }\n    return n ? m + 18.01524 : 0;\n  }\n\n  function mulberry32(a) {\n    return function () {\n      a |= 0; a = (a + 0x6D2B79F5) | 0;\n      var t = Math.imul(a ^ (a >>> 15), 1 | a);\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n  omni.onResult([\'kind\', \'length\', \'gc\', \'seed\', \'start\'], function (ctx) {\n    var kind = resolve(ctx.getRawInput(\'kind\'), { dna: \'dna\', rna: \'rna\', protein: \'protein\' }, \'dna\');\n    var n = Math.round(Number(ctx.getRawInput(\'length\')) || 0);\n    if (!(n > 0)) n = 0;\n    n = Math.min(n, 100000);\n    var gcTarget = Math.max(0, Math.min(100, Number(ctx.getRawInput(\'gc\')) || 0));\n    var seed = Math.round(Number(ctx.getRawInput(\'seed\')) || 0);\n    var start = /true|yes|1/i.test(String(ctx.getRawInput(\'start\') || \'\'));\n    if (!n) {\n      ctx.addHtml(block(\'Random sequence\', \'—\', \'Enter a length between 1 and 100 000.\'));\n      ctx.exportValue(\'gc_actual\', 0);\n      return;\n    }\n    var rnd = mulberry32(seed);\n    var seq = \'\', counts = {}, i, ch;\n    var seqAlpha = kind === \'protein\' ? \'ACDEFGHIKLMNPQRSTVWY\' : (kind === \'rna\' ? \'ACGU\' : \'ACGT\');\n    var gcPair = kind === \'rna\' ? [\'G\', \'C\'] : [\'G\', \'C\'];\n    for (i = 0; i < n; i++) {\n      if (kind === \'protein\') ch = seqAlpha.charAt(Math.floor(rnd() * seqAlpha.length) % seqAlpha.length);\n      else {\n        var r = rnd() * 100;\n        if (r < gcTarget / 2) ch = gcPair[0];\n        else if (r < gcTarget) ch = gcPair[1];\n        else ch = (rnd() < 0.5 ? \'A\' : (kind === \'rna\' ? \'U\' : \'T\'));\n      }\n      seq += ch;\n      counts[ch] = (counts[ch] || 0) + 1;\n    }\n    if (kind !== \'protein\' && start && n >= 3) {\n      seq = \'ATG\' + seq.slice(3);\n      counts = {};\n      for (i = 0; i < seq.length; i++) { ch = seq.charAt(i); counts[ch] = (counts[ch] || 0) + 1; }\n    }\n    var gcN = (counts.G || 0) + (counts.C || 0);\n    var pct = kind === \'protein\' ? 0 : gcN / n * 100;\n    ctx.exportValue(\'gc_actual\', Math.round(pct * 100) / 100);\n    var rows = [];\n    var keys = Object.keys(counts).sort();\n    for (i = 0; i < keys.length; i++) {\n      rows.push([keys[i], String(counts[keys[i]]), (counts[keys[i]] / n * 100).toFixed(2) + \' %\']);\n    }\n    var kindName = kind === \'protein\' ? \'protein\' : (kind === \'rna\' ? \'RNA\' : \'DNA\');\n    var head = block(\'Random \' + kindName + \' sequence — seed \' + seed,\n      \'Length      \' + n + \'\\nSeed        \' + seed\n      + (kind === \'protein\' ? \'\\nAlphabet    20 standard residues, uniform\'\n                            : \'\\nTarget GC   \' + gcTarget + \' %\\nRealised GC \' + pct.toFixed(2) + \' %\')\n      + (start && kind !== \'protein\' ? \'\\nStart       ATG forced at position 1\' : \'\'),\n      \'Reuse the seed and the length to get this exact sequence again.\');\n    ctx.addHtml(head + block(\'Sequence\', wrap(seq, 60)) + table(\'Composition\', [\'Symbol\', \'Count\', \'Share\'], rows));\n  });', NULL, 0, 1, 1, '2026-10-29 14:08:51', '2026-10-29 14:08:51'),
(207, 'codon-plot', 'biology', 'Codon Plot Calculator', 'Codon Plot Calculator', 'Codon Plot Calculator — Formula & Results', 'A codon plot shows where the rare codons sit along a coding sequence, not just how many there are. Free codon plot calculator: enter your values and get codon', 'A codon plot shows where the rare codons sit along a coding sequence, not just how many there are. It returns codons read, rare codons (w ≤ 0.2) and runs of 3+ rare codons, and the panel shows all of them at once.\n\nIt scores every codon for E. coli adaptation, draws the sequence as a track of bars and lists runs of rare codons — the clusters that stall a ribosome and cost protein yield. Press Calculate and the results appear in the grey boxes; after the first press they keep up with every edit, so there is no page to reload. Units are stated on every box and in every result, so a figure copied out of a protocol, a datasheet or a chart can be entered without converting it first.', '[{\"title\":\"The formula behind the Codon Plot\",\"html\":\"<p>plot the relative adaptiveness w of each codon in order; a cluster is 3 or more consecutive codons with w ≤ 0.2</p>\\n<figure class=\\\"calc-figure\\\"><img src=\\\"/uploads/biology/codon-plot.svg\\\" width=\\\"720\\\" height=\\\"300\\\" loading=\\\"lazy\\\" alt=\\\"Animated diagram: Codon Plot Calculator — Rare codons per 30-codon window along a 720 bp gene\\\" title=\\\"Codon Plot Calculator\\\"><figcaption>Rare codons per 30-codon window along a 720 bp gene</figcaption></figure>\\n<table><caption>The symbols in the formula</caption><thead><tr><th>Symbol</th><th>What it stands for</th><th>Unit</th></tr></thead><tbody><tr><td><code>w</code></td><td>relative adaptiveness of the codon in E. coli</td><td>0 – 1</td></tr><tr><td><code>window</code></td><td>codons per summary point on the plot</td><td>codons</td></tr><tr><td><code>cluster</code></td><td>consecutive rare codons</td><td>codons</td></tr></tbody></table>\"},{\"title\":\"How do I use the Codon Plot?\",\"html\":\"<p>Every input sits in the same order the formula is written, so the page reads like the equation.</p>\\n<ol><li>Paste the coding sequence — the page reads from the first base as codon 1.</li><li>Set the window if you want the summary coarser or finer than 30 codons.</li><li>Read the track first: a flat blue line with a handful of dips is a healthy gene. Then read the cluster list — a run of three or more rare codons is the part worth resynthesising.</li></ol>\"},{\"title\":\"A worked example\",\"html\":\"<p>Take the default values the page opens with: window size of <strong>30</strong> codons.</p>\\n<p>Those numbers come from the same solver the page runs in your browser, not from an illustration, so typing different inputs moves the answer exactly as the arithmetic says.</p>\"},{\"title\":\"What does the result mean?\",\"html\":\"<p>The number on its own is not a judgement. These are the bands most often used when the result is quoted in a paper, a report or a label:</p>\\n<table><caption>How to read the result</caption><thead><tr><th>Result</th><th>Band</th><th>What it means</th></tr></thead><tbody><tr><td>no cluster</td><td><strong>Even</strong></td><td>the gene has rare codons but they are spread out — usually fine</td></tr><tr><td>one cluster</td><td><strong>One hot spot</strong></td><td>often at the 5′ end; check the translation initiation region</td></tr><tr><td>two or three</td><td><strong>Several hot spots</strong></td><td>expect a yield penalty; consider changing those codons</td></tr><tr><td>four or more</td><td><strong>Poorly adapted</strong></td><td>resynthesise the gene rather than tune single codons</td></tr></tbody></table>\\n<ul><li><p>This is the plot that shows what a single CAI number cannot: a gene with a good average can still carry five consecutive codons at w = 0.06, and that run is what the ribosome queues on.</p></li><li><p>The y-axis is relative adaptiveness, not frequency. w = 1.00 means the codon is the host\'s most-used synonym for that amino acid; w = 0.03 means it is nearly unused.</p></li><li><p>Positions are codon numbers, not base numbers, so position 12 is bases 34–36.</p></li><li><p>Met, Trp and stop codons carry no adaptiveness — they are drawn as neutral points rather than scored, because there is no choice to make.</p></li></ul>\"},{\"title\":\"What are the common mistakes?\",\"html\":\"<p>These are the errors that account for almost every wrong answer people bring to this calculator:</p><ul><li>Plotting a genomic sequence with introns: the frame breaks at the first intron and every codon after it is wrong.</li><li>Treating a low average as the whole story, or a high one as a clean bill of health.</li><li>Ignoring an all-rare cluster at the very start, which affects initiation more than internal clusters affect elongation.</li></ul>\"},{\"title\":\"Calculators that go with this one\",\"html\":\"<p>This tool answers one step of the question. The neighbouring steps have their own pages:</p><p><a href=\\\"/biology/codon-adaptation-index\\\">Codon adaptation index</a>. <a href=\\\"/biology/codon-usage-calculator\\\">Codon usage</a>. <a href=\\\"/biology/orf-finder\\\">ORF finder</a>. <a href=\\\"/biology/multi-reverse-translate\\\">Multi reverse translate</a>.</p>\"}]', '[{\"q\":\"What does a codon plot show that the CAI does not?\",\"a\":\"Position. CAI averages the whole sequence; the plot shows where the rare codons are, so a cluster that stalls translation is visible instead of averaged away.\"},{\"q\":\"What counts as a rare codon?\",\"a\":\"Here, a codon whose relative adaptiveness in E. coli is 0.2 or below — roughly the bottom fifth of the usage range. The cut-off is stated on the page rather than implied.\"},{\"q\":\"Why are the stops and Met not scored?\",\"a\":\"Because they have a single codon. Adaptiveness measures a choice between synonyms, and there is none for those.\"},{\"q\":\"Can I use the plot for a human gene?\",\"a\":\"The weighting table here is E. coli. For a mammalian expression experiment the pattern of rare codons differs, and the codon adaptation index page lets you switch the host.\"},{\"q\":\"What does the Codon Plot actually calculate?\",\"a\":\"It returns codons read, rare codons (w ≤ 0.2) and runs of 3+ rare codons. Each one is derived by the formula on this page, so you can check any figure by hand.\"},{\"q\":\"Do I have to fill in every box?\",\"a\":\"Fill in the ones you know. The result boxes are computed from them, so you never enter a value the formula can derive — and if you change an input, every result updates with it.\"}]', '[{\"key\":\"sequence\",\"label\":\"Coding sequence (DNA)\",\"type\":\"text\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Paste the open reading frame; long sequences are summarised window by window\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":false},{\"key\":\"window\",\"label\":\"Window size\",\"type\":\"number\",\"default\":\"30\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"How many codons each summary point covers\",\"prefix\":\"\",\"suffix\":\"codons\",\"options\":[],\"output\":false},{\"key\":\"codons\",\"label\":\"Codons read\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Whole codons only\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":true},{\"key\":\"rare\",\"label\":\"Rare codons (w ≤ 0.2)\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":true},{\"key\":\"clusters\",\"label\":\"Runs of 3+ rare codons\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"The stalling risk\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":true}]', '[]', '{\"path\":\"/biology/codon-plot\",\"slug\":\"codon-plot\",\"cat\":\"biology\",\"name\":\"Codon Plot Calculator\",\"title\":\"Codon Plot Calculator — Formula & Results\",\"desc\":\"A codon plot shows where the rare codons sit along a coding sequence, not just how many there are. Free codon plot calculator: enter your values and get codon\",\"authors\":[],\"reviewers\":[],\"updated\":\"2026-10-29\",\"rate\":0,\"groups\":[{\"uid\":\"custom-codon-plot\",\"title\":\"\",\"desc\":\"\",\"m\":[[\"FR2\",[[{\"t\":\"v\",\"n\":\"sequence\",\"l\":\"Coding sequence (DNA)\",\"h\":\"Paste the open reading frame; long sequences are summarised window by window\",\"vt\":\"text\"},{\"t\":\"v\",\"n\":\"window\",\"l\":\"Window size\",\"h\":\"How many codons each summary point covers\",\"suf\":\"codons\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"codons\",\"l\":\"Codons read\",\"h\":\"Whole codons only\",\"oo\":1,\"vt\":\"numerical\"}],[{\"t\":\"v\",\"n\":\"rare\",\"l\":\"Rare codons (w ≤ 0.2)\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"clusters\",\"l\":\"Runs of 3+ rare codons\",\"h\":\"The stalling risk\",\"oo\":1,\"vt\":\"numerical\"}]]]]}],\"vars\":{\"sequence\":{\"type\":\"text\",\"rnd\":null,\"dfl\":[{\"v\":\"\",\"c\":null}]},\"window\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"30\",\"c\":null}]},\"codons\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"rare\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"clusters\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]}},\"datasets\":[],\"eq\":[],\"js\":\"function cleanSeq(raw, kind) {\\n    var s = String(raw || \'\').replace(/^>.*$/gm, \'\');\\n    s = s.replace(/[^A-Za-z]/g, \'\');\\n    return kind === \'protein\' ? s.toUpperCase() : s.toUpperCase().replace(/U/g, \'T\');\\n  }\\n  function esc(s) {\\n    return String(s).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\');\\n  }\\n  function block(title, body, note) {\\n    return \'<div class=\\\"calc-script-block\\\"><h3>\' + esc(title) + \'</h3><pre>\' + esc(body) + \'</pre>\'\\n      + (note ? \'<p class=\\\"calc-script-note\\\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\\n  }\\n  function table(title, head, rows, note) {\\n    var h = \'<tr>\' + head.map(function (c) { return \'<th>\' + esc(c) + \'</th>\'; }).join(\'\') + \'</tr>\';\\n    var b = rows.map(function (r) {\\n      return \'<tr>\' + r.map(function (c) { return \'<td>\' + esc(c) + \'</td>\'; }).join(\'\') + \'</tr>\';\\n    }).join(\'\');\\n    return \'<div class=\\\"calc-script-block\\\"><h3>\' + esc(title) + \'</h3>\'\\n      + \'<div class=\\\"calc-script-scroll\\\"><table class=\\\"calc-script-table\\\">\' + h + b + \'</table></div>\'\\n      + (note ? \'<p class=\\\"calc-script-note\\\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\\n  }\\n  function resolve(raw, map, fallback) {\\n    var n = String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\');\\n    if (Object.prototype.hasOwnProperty.call(map, raw)) return map[raw];\\n    var keys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });\\n    for (var i = 0; i < keys.length; i++) {\\n      var k = keys[i].toLowerCase().replace(/[^a-z0-9]/g, \'\');\\n      if (k && n.indexOf(k) >= 0) return map[keys[i]];\\n    }\\n    return fallback;\\n  }\\n  var BASES = \'TCAG\';\\n  var AA_ORDER = \'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG\';\\n  function aaOf(codon) {\\n    var i1 = BASES.indexOf(codon.charAt(0)), i2 = BASES.indexOf(codon.charAt(1)),\\n        i3 = BASES.indexOf(codon.charAt(2));\\n    if (i1 < 0 || i2 < 0 || i3 < 0) return null;\\n    return AA_ORDER.charAt(i1 * 16 + i2 * 4 + i3);\\n  }\\n\\n  // Relative adaptiveness in E. coli (the standard published table), two decimals.\\n  var W_ECOLI = {\\n    TTT: 0.57, TTC: 1.00, TTA: 0.13, TTG: 0.13, CTT: 0.10, CTC: 0.10, CTA: 0.04, CTG: 1.00,\\n    ATT: 0.51, ATC: 1.00, ATA: 0.08, ATG: 1.00,\\n    GTT: 0.60, GTC: 0.42, GTA: 0.27, GTG: 1.00,\\n    TCT: 0.60, TCC: 0.60, TCA: 0.14, TCG: 0.14, AGT: 0.31, AGC: 1.00,\\n    CCT: 0.35, CCC: 0.22, CCA: 0.35, CCG: 1.00,\\n    ACT: 0.49, ACC: 1.00, ACA: 0.13, ACG: 0.27,\\n    GCT: 0.53, GCC: 0.58, GCA: 0.45, GCG: 1.00,\\n    TAT: 0.57, TAC: 1.00, CAT: 0.57, CAC: 1.00, CAA: 0.34, CAG: 1.00,\\n    AAT: 0.49, AAC: 1.00, AAA: 1.00, AAG: 0.25, GAT: 0.63, GAC: 1.00,\\n    GAA: 0.68, GAG: 1.00, TGT: 0.46, TGC: 1.00, TGG: 1.00,\\n    CGT: 1.00, CGC: 0.55, CGA: 0.06, CGG: 0.03, AGA: 0.03, AGG: 0.02,\\n    GGT: 1.00, GGC: 0.74, GGA: 0.19, GGG: 0.15\\n  };\\n  // Eight steps from empty to full, so the track reads at a glance in text.\\n  var GLYPH = [\'·\', \'▁\', \'▂\', \'▃\', \'▄\', \'▅\', \'▆\', \'█\'];\\n  function bar(w) {\\n    var i = Math.round(Math.max(0, Math.min(1, w)) * (GLYPH.length - 1));\\n    return GLYPH[i];\\n  }\\n  omni.onResult([\'sequence\', \'window\'], function (ctx) {\\n    var seq = cleanSeq(ctx.getRawInput(\'sequence\'), \'dna\');\\n    var win = Math.round(Number(ctx.getRawInput(\'window\')) || 30);\\n    if (!(win >= 1)) win = 30;\\n    win = Math.min(win, 500);\\n    if (seq.length < 6) {\\n      ctx.addHtml(block(\'Codon plot\', \'—\', \'Paste a coding sequence of at least 6 bp.\'));\\n      ctx.exportValue(\'codons\', 0); ctx.exportValue(\'rare\', 0); ctx.exportValue(\'clusters\', 0);\\n      return;\\n    }\\n    var n = Math.floor(seq.length / 3);\\n    var scores = [], details = [], rare = 0, i;\\n    for (i = 0; i < n; i++) {\\n      var cod = seq.substr(i * 3, 3);\\n      var w = W_ECOLI[cod];\\n      if (w === undefined) { scores.push(null); details.push(null); continue; }\\n      scores.push(w);\\n      details.push(cod);\\n      if (w <= 0.2) rare++;\\n    }\\n    // runs of three or more scoring rare codons\\n    var runs = [], run = 0, runStart = 0;\\n    for (i = 0; i <= scores.length; i++) {\\n      var isRare = i < scores.length && scores[i] !== null && scores[i] <= 0.2;\\n      if (isRare) { if (run === 0) runStart = i + 1; run++; }\\n      else {\\n        if (run >= 3) runs.push({ start: runStart, len: run, codons: details.slice(runStart - 1, runStart - 1 + run).join(\' \') });\\n        run = 0;\\n      }\\n    }\\n    // window averages for the summary table\\n    var rows = [], worst = null;\\n    for (i = 0; i < n; i += win) {\\n      var sum = 0, cnt = 0, rareInWin = 0;\\n      for (var j = i; j < Math.min(i + win, n); j++) {\\n        if (scores[j] === null) continue;\\n        sum += scores[j]; cnt++;\\n        if (scores[j] <= 0.2) rareInWin++;\\n      }\\n      var mean = cnt ? sum / cnt : 0;\\n      rows.push([(i + 1) + \'–\' + Math.min(i + win, n), cnt ? mean.toFixed(2) : \'—\',\\n                 String(rareInWin), rareInWin >= 3 ? \'check\' : \'ok\']);\\n      if (!worst || rareInWin > worst.rare) worst = { start: i + 1, rare: rareInWin };\\n    }\\n    // the track itself, wrapped to 60 codons per line\\n    var track = \'\';\\n    for (i = 0; i < n; i += 60) {\\n      var line = \'\';\\n      for (var k = i; k < Math.min(i + 60, n); k++) line += scores[k] === null ? \'?\' : bar(scores[k]);\\n      track += line + \'\\\\n\';\\n    }\\n    var meanAll = 0, cntAll = 0;\\n    for (i = 0; i < n; i++) if (scores[i] !== null) { meanAll += scores[i]; cntAll++; }\\n    meanAll = cntAll ? meanAll / cntAll : 0;\\n    ctx.exportValue(\'codons\', n);\\n    ctx.exportValue(\'rare\', rare);\\n    ctx.exportValue(\'clusters\', runs.length);\\n    var head = block(\'Codon plot — \' + n + \' codons\',\\n      \'Mean w            \' + meanAll.toFixed(3) + \'\\\\nRare codons       \' + rare\\n      + \'\\\\nRuns of 3+        \' + runs.length\\n      + \'\\\\nWorst window      \' + (worst ? worst.start + \' (first codon)\' : \'—\'),\\n      \'Legend: · w=0  ▁▂▃▄▅▆ rising  █ w=1.  A codon the table does not know is drawn as ?.\');\\n    var runRows = runs.slice(0, 12).map(function (r) {\\n      return [String(r.start), String(r.len), r.codons];\\n    });\\n    var html = head + block(\'Track (one character per codon, 60 per line)\', track)\\n      + table(\'Windows\', [\'Codons\', \'Mean w\', \'Rare\', \'Verdict\'], rows.slice(0, 20),\\n              rows.length > 20 ? \'First 20 windows shown.\' : \'\')\\n      + table(\'Runs of three or more rare codons\', [\'First codon\', \'Length\', \'Codons\'],\\n              runRows.length ? runRows : [[\'—\', \'0\', \'none\']],\\n              runs.length > 12 ? \'First 12 runs shown.\' : \'\');\\n    ctx.addHtml(html);\\n  });\",\"needsJs\":false}', 'dna', '', 'published', 0, 1000, 0, 'function cleanSeq(raw, kind) {\n    var s = String(raw || \'\').replace(/^>.*$/gm, \'\');\n    s = s.replace(/[^A-Za-z]/g, \'\');\n    return kind === \'protein\' ? s.toUpperCase() : s.toUpperCase().replace(/U/g, \'T\');\n  }\n  function esc(s) {\n    return String(s).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\');\n  }\n  function block(title, body, note) {\n    return \'<div class=\"calc-script-block\"><h3>\' + esc(title) + \'</h3><pre>\' + esc(body) + \'</pre>\'\n      + (note ? \'<p class=\"calc-script-note\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\n  }\n  function table(title, head, rows, note) {\n    var h = \'<tr>\' + head.map(function (c) { return \'<th>\' + esc(c) + \'</th>\'; }).join(\'\') + \'</tr>\';\n    var b = rows.map(function (r) {\n      return \'<tr>\' + r.map(function (c) { return \'<td>\' + esc(c) + \'</td>\'; }).join(\'\') + \'</tr>\';\n    }).join(\'\');\n    return \'<div class=\"calc-script-block\"><h3>\' + esc(title) + \'</h3>\'\n      + \'<div class=\"calc-script-scroll\"><table class=\"calc-script-table\">\' + h + b + \'</table></div>\'\n      + (note ? \'<p class=\"calc-script-note\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\n  }\n  function resolve(raw, map, fallback) {\n    var n = String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\');\n    if (Object.prototype.hasOwnProperty.call(map, raw)) return map[raw];\n    var keys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });\n    for (var i = 0; i < keys.length; i++) {\n      var k = keys[i].toLowerCase().replace(/[^a-z0-9]/g, \'\');\n      if (k && n.indexOf(k) >= 0) return map[keys[i]];\n    }\n    return fallback;\n  }\n  var BASES = \'TCAG\';\n  var AA_ORDER = \'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG\';\n  function aaOf(codon) {\n    var i1 = BASES.indexOf(codon.charAt(0)), i2 = BASES.indexOf(codon.charAt(1)),\n        i3 = BASES.indexOf(codon.charAt(2));\n    if (i1 < 0 || i2 < 0 || i3 < 0) return null;\n    return AA_ORDER.charAt(i1 * 16 + i2 * 4 + i3);\n  }\n\n  // Relative adaptiveness in E. coli (the standard published table), two decimals.\n  var W_ECOLI = {\n    TTT: 0.57, TTC: 1.00, TTA: 0.13, TTG: 0.13, CTT: 0.10, CTC: 0.10, CTA: 0.04, CTG: 1.00,\n    ATT: 0.51, ATC: 1.00, ATA: 0.08, ATG: 1.00,\n    GTT: 0.60, GTC: 0.42, GTA: 0.27, GTG: 1.00,\n    TCT: 0.60, TCC: 0.60, TCA: 0.14, TCG: 0.14, AGT: 0.31, AGC: 1.00,\n    CCT: 0.35, CCC: 0.22, CCA: 0.35, CCG: 1.00,\n    ACT: 0.49, ACC: 1.00, ACA: 0.13, ACG: 0.27,\n    GCT: 0.53, GCC: 0.58, GCA: 0.45, GCG: 1.00,\n    TAT: 0.57, TAC: 1.00, CAT: 0.57, CAC: 1.00, CAA: 0.34, CAG: 1.00,\n    AAT: 0.49, AAC: 1.00, AAA: 1.00, AAG: 0.25, GAT: 0.63, GAC: 1.00,\n    GAA: 0.68, GAG: 1.00, TGT: 0.46, TGC: 1.00, TGG: 1.00,\n    CGT: 1.00, CGC: 0.55, CGA: 0.06, CGG: 0.03, AGA: 0.03, AGG: 0.02,\n    GGT: 1.00, GGC: 0.74, GGA: 0.19, GGG: 0.15\n  };\n  // Eight steps from empty to full, so the track reads at a glance in text.\n  var GLYPH = [\'·\', \'▁\', \'▂\', \'▃\', \'▄\', \'▅\', \'▆\', \'█\'];\n  function bar(w) {\n    var i = Math.round(Math.max(0, Math.min(1, w)) * (GLYPH.length - 1));\n    return GLYPH[i];\n  }\n  omni.onResult([\'sequence\', \'window\'], function (ctx) {\n    var seq = cleanSeq(ctx.getRawInput(\'sequence\'), \'dna\');\n    var win = Math.round(Number(ctx.getRawInput(\'window\')) || 30);\n    if (!(win >= 1)) win = 30;\n    win = Math.min(win, 500);\n    if (seq.length < 6) {\n      ctx.addHtml(block(\'Codon plot\', \'—\', \'Paste a coding sequence of at least 6 bp.\'));\n      ctx.exportValue(\'codons\', 0); ctx.exportValue(\'rare\', 0); ctx.exportValue(\'clusters\', 0);\n      return;\n    }\n    var n = Math.floor(seq.length / 3);\n    var scores = [], details = [], rare = 0, i;\n    for (i = 0; i < n; i++) {\n      var cod = seq.substr(i * 3, 3);\n      var w = W_ECOLI[cod];\n      if (w === undefined) { scores.push(null); details.push(null); continue; }\n      scores.push(w);\n      details.push(cod);\n      if (w <= 0.2) rare++;\n    }\n    // runs of three or more scoring rare codons\n    var runs = [], run = 0, runStart = 0;\n    for (i = 0; i <= scores.length; i++) {\n      var isRare = i < scores.length && scores[i] !== null && scores[i] <= 0.2;\n      if (isRare) { if (run === 0) runStart = i + 1; run++; }\n      else {\n        if (run >= 3) runs.push({ start: runStart, len: run, codons: details.slice(runStart - 1, runStart - 1 + run).join(\' \') });\n        run = 0;\n      }\n    }\n    // window averages for the summary table\n    var rows = [], worst = null;\n    for (i = 0; i < n; i += win) {\n      var sum = 0, cnt = 0, rareInWin = 0;\n      for (var j = i; j < Math.min(i + win, n); j++) {\n        if (scores[j] === null) continue;\n        sum += scores[j]; cnt++;\n        if (scores[j] <= 0.2) rareInWin++;\n      }\n      var mean = cnt ? sum / cnt : 0;\n      rows.push([(i + 1) + \'–\' + Math.min(i + win, n), cnt ? mean.toFixed(2) : \'—\',\n                 String(rareInWin), rareInWin >= 3 ? \'check\' : \'ok\']);\n      if (!worst || rareInWin > worst.rare) worst = { start: i + 1, rare: rareInWin };\n    }\n    // the track itself, wrapped to 60 codons per line\n    var track = \'\';\n    for (i = 0; i < n; i += 60) {\n      var line = \'\';\n      for (var k = i; k < Math.min(i + 60, n); k++) line += scores[k] === null ? \'?\' : bar(scores[k]);\n      track += line + \'\\n\';\n    }\n    var meanAll = 0, cntAll = 0;\n    for (i = 0; i < n; i++) if (scores[i] !== null) { meanAll += scores[i]; cntAll++; }\n    meanAll = cntAll ? meanAll / cntAll : 0;\n    ctx.exportValue(\'codons\', n);\n    ctx.exportValue(\'rare\', rare);\n    ctx.exportValue(\'clusters\', runs.length);\n    var head = block(\'Codon plot — \' + n + \' codons\',\n      \'Mean w            \' + meanAll.toFixed(3) + \'\\nRare codons       \' + rare\n      + \'\\nRuns of 3+        \' + runs.length\n      + \'\\nWorst window      \' + (worst ? worst.start + \' (first codon)\' : \'—\'),\n      \'Legend: · w=0  ▁▂▃▄▅▆ rising  █ w=1.  A codon the table does not know is drawn as ?.\');\n    var runRows = runs.slice(0, 12).map(function (r) {\n      return [String(r.start), String(r.len), r.codons];\n    });\n    var html = head + block(\'Track (one character per codon, 60 per line)\', track)\n      + table(\'Windows\', [\'Codons\', \'Mean w\', \'Rare\', \'Verdict\'], rows.slice(0, 20),\n              rows.length > 20 ? \'First 20 windows shown.\' : \'\')\n      + table(\'Runs of three or more rare codons\', [\'First codon\', \'Length\', \'Codons\'],\n              runRows.length ? runRows : [[\'—\', \'0\', \'none\']],\n              runs.length > 12 ? \'First 12 runs shown.\' : \'\');\n    ctx.addHtml(html);\n  });', NULL, 0, 1, 1, '2026-10-29 14:08:51', '2026-10-29 14:08:51'),
(208, 'dog-coat-color', 'biology', 'Dog Coat Colour Calculator', 'Dog Coat Colour Calculator', 'Dog Coat Colour Calculator — Formula & Results', 'Dog coat colour comes from four genes acting in a fixed order: E, K, B and D. Free dog coat colour calculator: enter your values and get loci answered instant', 'Dog coat colour comes from four genes acting in a fixed order: E, K, B and D. It returns loci answered, and the panel shows all of them at once.\n\nThis page takes the genotype at those four loci and returns the colour you would see, the full gene order, and what each locus is doing. Every result is derived from the boxes you fill in, so changing one input updates the whole panel at once. Units are stated on every box and in every result, so a figure copied out of a protocol, a datasheet or a chart can be entered without converting it first.', '[{\"title\":\"The formula behind the Dog Coat Colour\",\"html\":\"<p>E → K → B → D, in that order: E decides if black is made, K overrides the agouti pattern, B sets black vs brown, D dilutes whatever pigment is left</p>\\n<figure class=\\\"calc-figure\\\"><img src=\\\"/uploads/biology/dog-coat-color.svg\\\" width=\\\"720\\\" height=\\\"300\\\" loading=\\\"lazy\\\" alt=\\\"Animated diagram: Dog Coat Colour Calculator — Phenotype counts in a litter of 8 from a typical cross\\\" title=\\\"Dog Coat Colour Calculator\\\"><figcaption>Phenotype counts in a litter of 8 from a typical cross</figcaption></figure>\\n<table><caption>The symbols in the formula</caption><thead><tr><th>Symbol</th><th>What it stands for</th><th>Unit</th></tr></thead><tbody><tr><td><code>E</code></td><td>extension — e/e blocks all black pigment</td><td>locus</td></tr><tr><td><code>K</code></td><td>dominant black: K^B solid, K^br brindle, k^y allows agouti</td><td>locus</td></tr><tr><td><code>B</code></td><td>b/b turns black pigment brown</td><td>locus</td></tr><tr><td><code>D</code></td><td>d/d dilutes black to blue and brown to lilac</td><td>locus</td></tr></tbody></table>\"},{\"title\":\"How do I use the Dog Coat Colour?\",\"html\":\"<p>The form asks only for what the formula needs — nothing is optional decoration.</p>\\n<ol><li>Enter the genotype at each locus — a dog can only be E/E or E/e if it shows any black at all.</li><li>Tick ticking if the dog has flecks on its white areas; that is the T locus and it is not part of the four-locus colour model.</li><li>Read the predicted colour, then the gene-order explanation: it tells you which locus is actually responsible, which is what matters if you are planning a litter.</li></ol>\"},{\"title\":\"A worked example\",\"html\":\"<p>Take the default values the page opens with: ticking or roan spotting (t locus) of <strong>0</strong>.</p>\\n<p>The arithmetic is the page\'s own: change one box and the result moves by the amount the formula implies, which is the quickest way to convince yourself the tool is honest.</p>\"},{\"title\":\"What does the result mean?\",\"html\":\"<p>A raw figure only means something next to the bands it is normally judged against. Here is the scale that goes with this one:</p>\\n<table><caption>How to read the result</caption><thead><tr><th>Result</th><th>Band</th><th>What it means</th></tr></thead><tbody><tr><td>e/e</td><td><strong>Red, yellow or cream</strong></td><td>no black pigment can be made, whatever the other loci say</td></tr><tr><td>E/- + K^B</td><td><strong>Solid black</strong></td><td>dominant black overrides the agouti pattern</td></tr><tr><td>E/- + k^y/k^y + B/-</td><td><strong>Black, or agouti if A allows</strong></td><td>the A locus decides the pattern</td></tr><tr><td>b/b</td><td><strong>Chocolate or liver</strong></td><td>black pigment turned brown</td></tr><tr><td>d/d</td><td><strong>Blue, lilac or isabella</strong></td><td>dilution of whatever the dog would otherwise be</td></tr></tbody></table>\\n<ul><li><p>The order matters and is the whole point of the page: a b/b dog that is also e/e is not chocolate, because with no black pigment there is nothing for B to turn brown. Epistasis runs E over K over A over B over D.</p></li><li><p>Dilution is a pigment-density effect, not a colour: d/d turns black into blue and brown into lilac, and dilutes red to a paler cream.</p></li><li><p>Two loci that often surprise people are missing from this model on purpose — the A (agouti) pattern, which needs a full allele series to be useful, and the merle locus, which is incompletely dominant and often unhealthy in homozygotes.</p></li><li><p>Locus notation varies by author (E, EXT; K, CBD103; B, TYRP1; D, MLPH). The phenotype is the same; the letters are convention.</p></li></ul>\"},{\"title\":\"What are the common mistakes?\",\"html\":\"<p>The arithmetic is simple; the inputs are where things go wrong. The usual culprits:</p><ul><li>Naming a colour from the B locus alone: a b/b dog with no black pigment is red, not chocolate.</li><li>Assuming two chocolate parents give only chocolate puppies — they do, at the B locus, but E and K still decide whether any black pigment exists to be browned.</li><li>Breeding two merle dogs because the colours look interesting; double merle causes deafness and eye defects, which is why merle is not offered here.</li><li>Reading K^br as \\\"any brindle pattern\\\": brindle needs black pigment to stripe, so an e/e dog cannot be brindled.</li></ul>\"},{\"title\":\"Calculators that go with this one\",\"html\":\"<p>If you need the rest of the working, these cover the adjacent quantities:</p><p><a href=\\\"/biology/rabbit-color\\\">Rabbit colour genetics</a>. <a href=\\\"/biology/dog-size\\\">Dog size</a>. <a href=\\\"/biology/punnett-square\\\">Punnett square</a>. <a href=\\\"/biology/dihybrid-cross\\\">Dihybrid cross</a>.</p>\"}]', '[{\"q\":\"How is dog coat colour inherited?\",\"a\":\"Through a small set of loci acting in a fixed order. E decides whether black pigment is produced at all; K overrides the agouti pattern with solid black or brindle; A sets the pattern; B makes black pigment brown; D dilutes the result.\"},{\"q\":\"Can two black Labradors have yellow puppies?\",\"a\":\"Yes — if both parents are E/e. The puppies that inherit e from both sides cannot make black pigment and are yellow, whatever their B and K loci say.\"},{\"q\":\"What makes a dog chocolate instead of black?\",\"a\":\"Two copies of b at the TYRP1 locus, plus at least one E so that black pigment is actually being made. Without E, the B locus has nothing to act on.\"},{\"q\":\"Is this a DNA test?\",\"a\":\"No. It predicts a phenotype from a genotype you enter. The loci are real and commercially tested, but a prediction from a pedigree is only as good as the assumed genotypes.\"},{\"q\":\"What does the Dog Coat Colour actually calculate?\",\"a\":\"It returns loci answered. Each one is derived by the formula on this page, so you can check any figure by hand.\"},{\"q\":\"Do I have to fill in every box?\",\"a\":\"Fill in the ones you know. The result boxes are computed from them, so you never enter a value the formula can derive — and if you change an input, every result updates with it.\"}]', '[{\"key\":\"e_locus\",\"label\":\"E locus (extension)\",\"type\":\"select\",\"default\":\"e-e-black-allowed-carries-red\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[[\"e-e-black-allowed\",\"E/E — black allowed\",\"EE\"],[\"e-e-black-allowed-carries-red\",\"E/e — black allowed, carries red\",\"Ee\"],[\"e-e-no-black-red-or-yellow\",\"e/e — no black, red or yellow\",\"ee\"]],\"output\":false},{\"key\":\"k_locus\",\"label\":\"K locus (dominant black / brindle)\",\"type\":\"select\",\"default\":\"k-y-k-y-lets-the-a-locus-show\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[[\"k-b-solid-black\",\"K^B — solid black\",\"KB\"],[\"k-br-brindle\",\"K^br — brindle\",\"KBR\"],[\"k-y-k-y-lets-the-a-locus-show\",\"k^y/k^y — lets the A locus show\",\"ky\"]],\"output\":false},{\"key\":\"b_locus\",\"label\":\"B locus (brown)\",\"type\":\"select\",\"default\":\"b-b-black-carries-brown\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[[\"b-b-black-pigment\",\"B/B — black pigment\",\"BB\"],[\"b-b-black-carries-brown\",\"B/b — black, carries brown\",\"Bb\"],[\"b-b-brown-chocolate\",\"b/b — brown (chocolate)\",\"bb\"]],\"output\":false},{\"key\":\"d_locus\",\"label\":\"D locus (dilution)\",\"type\":\"select\",\"default\":\"d-d-full-colour-carries-dilute\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[[\"d-d-full-colour\",\"D/D — full colour\",\"DD\"],[\"d-d-full-colour-carries-dilute\",\"D/d — full colour, carries dilute\",\"Dd\"],[\"d-d-diluted-blue-lilac\",\"d/d — diluted (blue, lilac)\",\"dd\"]],\"output\":false},{\"key\":\"ticking\",\"label\":\"Ticking or roan spotting (T locus)\",\"type\":\"checkbox\",\"default\":\"0\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Small coloured flecks on white areas\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":false},{\"key\":\"loci\",\"label\":\"Loci answered\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Always 4\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":true}]', '[]', '{\"path\":\"/biology/dog-coat-color\",\"slug\":\"dog-coat-color\",\"cat\":\"biology\",\"name\":\"Dog Coat Colour Calculator\",\"title\":\"Dog Coat Colour Calculator — Formula & Results\",\"desc\":\"Dog coat colour comes from four genes acting in a fixed order: E, K, B and D. Free dog coat colour calculator: enter your values and get loci answered instant\",\"authors\":[],\"reviewers\":[],\"updated\":\"2026-10-29\",\"rate\":0,\"groups\":[{\"uid\":\"custom-dog-coat-color\",\"title\":\"\",\"desc\":\"\",\"m\":[[\"FR2\",[[{\"t\":\"v\",\"n\":\"e_locus\",\"l\":\"E locus (extension)\",\"vt\":\"valueSelect\",\"ds\":\"ds-e_locus\",\"opts\":[[\"e-e-black-allowed\",\"E/E — black allowed\",\"EE\"],[\"e-e-black-allowed-carries-red\",\"E/e — black allowed, carries red\",\"Ee\"],[\"e-e-no-black-red-or-yellow\",\"e/e — no black, red or yellow\",\"ee\"]]},{\"t\":\"v\",\"n\":\"k_locus\",\"l\":\"K locus (dominant black / brindle)\",\"vt\":\"valueSelect\",\"ds\":\"ds-k_locus\",\"opts\":[[\"k-b-solid-black\",\"K^B — solid black\",\"KB\"],[\"k-br-brindle\",\"K^br — brindle\",\"KBR\"],[\"k-y-k-y-lets-the-a-locus-show\",\"k^y/k^y — lets the A locus show\",\"ky\"]]},{\"t\":\"v\",\"n\":\"b_locus\",\"l\":\"B locus (brown)\",\"vt\":\"valueSelect\",\"ds\":\"ds-b_locus\",\"opts\":[[\"b-b-black-pigment\",\"B/B — black pigment\",\"BB\"],[\"b-b-black-carries-brown\",\"B/b — black, carries brown\",\"Bb\"],[\"b-b-brown-chocolate\",\"b/b — brown (chocolate)\",\"bb\"]]}],[{\"t\":\"v\",\"n\":\"d_locus\",\"l\":\"D locus (dilution)\",\"vt\":\"valueSelect\",\"ds\":\"ds-d_locus\",\"opts\":[[\"d-d-full-colour\",\"D/D — full colour\",\"DD\"],[\"d-d-full-colour-carries-dilute\",\"D/d — full colour, carries dilute\",\"Dd\"],[\"d-d-diluted-blue-lilac\",\"d/d — diluted (blue, lilac)\",\"dd\"]]},{\"t\":\"v\",\"n\":\"ticking\",\"l\":\"Ticking or roan spotting (T locus)\",\"h\":\"Small coloured flecks on white areas\",\"vt\":\"valueSelect\",\"ds\":\"ds-ticking\",\"opts\":[[\"yes\",\"Yes\",\"1\"],[\"no\",\"No\",\"0\"]]},{\"t\":\"v\",\"n\":\"loci\",\"l\":\"Loci answered\",\"h\":\"Always 4\",\"oo\":1,\"vt\":\"numerical\"}]]]]}],\"vars\":{\"e_locus\":{\"type\":\"valueSelect\",\"rnd\":null,\"dfl\":[{\"v\":\"e-e-black-allowed-carries-red\",\"c\":null}],\"ds\":\"ds-e_locus\"},\"k_locus\":{\"type\":\"valueSelect\",\"rnd\":null,\"dfl\":[{\"v\":\"k-y-k-y-lets-the-a-locus-show\",\"c\":null}],\"ds\":\"ds-k_locus\"},\"b_locus\":{\"type\":\"valueSelect\",\"rnd\":null,\"dfl\":[{\"v\":\"b-b-black-carries-brown\",\"c\":null}],\"ds\":\"ds-b_locus\"},\"d_locus\":{\"type\":\"valueSelect\",\"rnd\":null,\"dfl\":[{\"v\":\"d-d-full-colour-carries-dilute\",\"c\":null}],\"ds\":\"ds-d_locus\"},\"ticking\":{\"type\":\"valueSelect\",\"rnd\":null,\"dfl\":[{\"v\":\"no\",\"c\":null}],\"ds\":\"ds-ticking\"},\"loci\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]}},\"datasets\":{\"ds-e_locus\":{\"name\":\"E locus (extension)\",\"uiType\":\"RADIO\",\"options\":[{\"uid\":\"e-e-black-allowed\",\"label\":\"E/E — black allowed\",\"value\":\"EE\"},{\"uid\":\"e-e-black-allowed-carries-red\",\"label\":\"E/e — black allowed, carries red\",\"value\":\"Ee\"},{\"uid\":\"e-e-no-black-red-or-yellow\",\"label\":\"e/e — no black, red or yellow\",\"value\":\"ee\"}]},\"ds-k_locus\":{\"name\":\"K locus (dominant black / brindle)\",\"uiType\":\"RADIO\",\"options\":[{\"uid\":\"k-b-solid-black\",\"label\":\"K^B — solid black\",\"value\":\"KB\"},{\"uid\":\"k-br-brindle\",\"label\":\"K^br — brindle\",\"value\":\"KBR\"},{\"uid\":\"k-y-k-y-lets-the-a-locus-show\",\"label\":\"k^y/k^y — lets the A locus show\",\"value\":\"ky\"}]},\"ds-b_locus\":{\"name\":\"B locus (brown)\",\"uiType\":\"RADIO\",\"options\":[{\"uid\":\"b-b-black-pigment\",\"label\":\"B/B — black pigment\",\"value\":\"BB\"},{\"uid\":\"b-b-black-carries-brown\",\"label\":\"B/b — black, carries brown\",\"value\":\"Bb\"},{\"uid\":\"b-b-brown-chocolate\",\"label\":\"b/b — brown (chocolate)\",\"value\":\"bb\"}]},\"ds-d_locus\":{\"name\":\"D locus (dilution)\",\"uiType\":\"RADIO\",\"options\":[{\"uid\":\"d-d-full-colour\",\"label\":\"D/D — full colour\",\"value\":\"DD\"},{\"uid\":\"d-d-full-colour-carries-dilute\",\"label\":\"D/d — full colour, carries dilute\",\"value\":\"Dd\"},{\"uid\":\"d-d-diluted-blue-lilac\",\"label\":\"d/d — diluted (blue, lilac)\",\"value\":\"dd\"}]},\"ds-ticking\":{\"name\":\"Ticking or roan spotting (T locus)\",\"uiType\":\"RADIO\",\"options\":[{\"uid\":\"yes\",\"label\":\"Yes\",\"value\":\"1\"},{\"uid\":\"no\",\"label\":\"No\",\"value\":\"0\"}]}},\"eq\":[],\"js\":\"function cleanSeq(raw, kind) {\\n    var s = String(raw || \'\').replace(/^>.*$/gm, \'\');\\n    s = s.replace(/[^A-Za-z]/g, \'\');\\n    return kind === \'protein\' ? s.toUpperCase() : s.toUpperCase().replace(/U/g, \'T\');\\n  }\\n  function esc(s) {\\n    return String(s).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\');\\n  }\\n  function block(title, body, note) {\\n    return \'<div class=\\\"calc-script-block\\\"><h3>\' + esc(title) + \'</h3><pre>\' + esc(body) + \'</pre>\'\\n      + (note ? \'<p class=\\\"calc-script-note\\\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\\n  }\\n  function table(title, head, rows, note) {\\n    var h = \'<tr>\' + head.map(function (c) { return \'<th>\' + esc(c) + \'</th>\'; }).join(\'\') + \'</tr>\';\\n    var b = rows.map(function (r) {\\n      return \'<tr>\' + r.map(function (c) { return \'<td>\' + esc(c) + \'</td>\'; }).join(\'\') + \'</tr>\';\\n    }).join(\'\');\\n    return \'<div class=\\\"calc-script-block\\\"><h3>\' + esc(title) + \'</h3>\'\\n      + \'<div class=\\\"calc-script-scroll\\\"><table class=\\\"calc-script-table\\\">\' + h + b + \'</table></div>\'\\n      + (note ? \'<p class=\\\"calc-script-note\\\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\\n  }\\n  function resolve(raw, map, fallback) {\\n    var n = String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\');\\n    if (Object.prototype.hasOwnProperty.call(map, raw)) return map[raw];\\n    var keys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });\\n    for (var i = 0; i < keys.length; i++) {\\n      var k = keys[i].toLowerCase().replace(/[^a-z0-9]/g, \'\');\\n      if (k && n.indexOf(k) >= 0) return map[keys[i]];\\n    }\\n    return fallback;\\n  }\\n  var BASES = \'TCAG\';\\n  var AA_ORDER = \'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG\';\\n  function aaOf(codon) {\\n    var i1 = BASES.indexOf(codon.charAt(0)), i2 = BASES.indexOf(codon.charAt(1)),\\n        i3 = BASES.indexOf(codon.charAt(2));\\n    if (i1 < 0 || i2 < 0 || i3 < 0) return null;\\n    return AA_ORDER.charAt(i1 * 16 + i2 * 4 + i3);\\n  }\\n\\n  function norm(raw) { return String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\'); }\\n  /*\\n   * The panel stores a choice as a uid derived from the option *label*, so every\\n   * genotype label for one locus begins with the same letters (\\\"e-e-...\\\", \\\"b-b-...\\\").\\n   * Reading the letters back out would always pick the first option, so each locus\\n   * is read from the words that actually distinguish its options.\\n   */\\n  function pickE(raw) {\\n    var n = norm(raw);\\n    if (n.indexOf(\'noblack\') >= 0) return \'ee\';\\n    if (n.indexOf(\'carries\') >= 0) return \'Ee\';\\n    return \'EE\';\\n  }\\n  function pickK(raw) {\\n    var n = norm(raw);\\n    if (n.indexOf(\'brindle\') >= 0) return \'KBR\';\\n    if (n.indexOf(\'solid\') >= 0) return \'KB\';\\n    return \'ky\';\\n  }\\n  function pickB(raw) {\\n    var n = norm(raw);\\n    if (n.indexOf(\'chocolate\') >= 0 || n.indexOf(\'brownbrown\') >= 0) return \'bb\';\\n    if (n.indexOf(\'carries\') >= 0) return \'Bb\';\\n    return \'BB\';\\n  }\\n  function pickD(raw) {\\n    var n = norm(raw);\\n    if (n.indexOf(\'diluted\') >= 0 || n.indexOf(\'lilac\') >= 0) return \'dd\';\\n    if (n.indexOf(\'carries\') >= 0) return \'Dd\';\\n    return \'DD\';\\n  }\\n  var E_MAP = { ee: \'red/yellow\', Ee: \'has black\', EE: \'has black\' };\\n  var B_MAP = { BB: \'black\', Bb: \'black (carries brown)\', bb: \'brown\' };\\n  var D_MAP = { DD: \'full\', Dd: \'full (carries dilute)\', dd: \'dilute\' };\\n  function colourOf(e, k, b, d) {\\n    // e/e: no black pigment at all — the other loci cannot put colour back\\n    if (e === \'ee\') {\\n      return d === \'dd\' ? \'cream (dilute red)\' : \'red / yellow / golden\';\\n    }\\n    // K^B makes the dog solid black whatever A would otherwise do\\n    if (k === \'KB\') {\\n      if (d === \'dd\') return \'blue (dilute black)\';\\n      return \'solid black\';\\n    }\\n    if (k === \'KBR\') {\\n      if (d === \'dd\') return \'blue brindle (dilute brindle)\';\\n      return \'brindle\';\\n    }\\n    // k^y/k^y: the A locus shows; we do not model A, so both pigment states appear\\n    if (b === \'bb\') {\\n      if (d === \'dd\') return \'lilac / isabella (dilute chocolate)\';\\n      if (k === \'ky\') return \'chocolate (or agouti-patterned brown)\';\\n      return \'chocolate\';\\n    }\\n    if (d === \'dd\') return k === \'ky\' ? \'blue, or blue agouti\' : \'blue\';\\n    return k === \'ky\' ? \'black, or the agouti pattern (sable, tan points)\' : \'black\';\\n  }\\n  omni.onResult([\'e_locus\', \'k_locus\', \'b_locus\', \'d_locus\', \'ticking\'], function (ctx) {\\n    var e = pickE(ctx.getRawInput(\'e_locus\'));\\n    var k = pickK(ctx.getRawInput(\'k_locus\'));\\n    var b = pickB(ctx.getRawInput(\'b_locus\'));\\n    var d = pickD(ctx.getRawInput(\'d_locus\'));\\n    var ticking = /true|yes|1/i.test(String(ctx.getRawInput(\'ticking\') || \'\'));\\n    var colour = colourOf(e, k, b, d);\\n    if (ticking) colour += \', with ticking\';\\n    ctx.exportValue(\'loci\', 4);\\n    var rows = [\\n      [\'E (extension)\', e, E_MAP[e] || \'\'],\\n      [\'K (dominant black)\', k === \'KB\' ? \'K^B\' : (k === \'KBR\' ? \'K^br\' : \'k^y/k^y\'), k === \'KB\' ? \'solid black\' : (k === \'KBR\' ? \'brindle\' : \'lets agouti show\')],\\n      [\'B (brown)\', b, B_MAP[b] || \'\'],\\n      [\'D (dilution)\', d, D_MAP[d] || \'\'],\\n      [\'T (ticking)\', ticking ? \'T/-\' : \'t/t\', ticking ? \'flecks on white\' : \'no ticking\']\\n    ];\\n    var html = block(\'Predicted coat colour\',\\n      \'Genotype   E: \' + e + \'   K: \' + (k === \'KB\' ? \'K^B\' : (k === \'KBR\' ? \'K^br\' : \'k^y/k^y\'))\\n      + \'   B: \' + b + \'   D: \' + d + \'\\\\nPhenotype  \' + colour,\\n      e === \'ee\'\\n        ? \'With e/e no black pigment is made, so the B, K and D loci cannot darken the dog — this is why two yellow Labradors never produce a black puppy.\'\\n        : \'The loci act in the order E then K then A then B then D; the first one that decides the outcome wins.\');\\n    html += table(\'What each locus is doing\', [\'Locus\', \'Genotype\', \'Effect\'], rows);\\n    ctx.addHtml(html);\\n  });\",\"needsJs\":false}', 'paw', '', 'published', 0, 1000, 0, 'function cleanSeq(raw, kind) {\n    var s = String(raw || \'\').replace(/^>.*$/gm, \'\');\n    s = s.replace(/[^A-Za-z]/g, \'\');\n    return kind === \'protein\' ? s.toUpperCase() : s.toUpperCase().replace(/U/g, \'T\');\n  }\n  function esc(s) {\n    return String(s).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\');\n  }\n  function block(title, body, note) {\n    return \'<div class=\"calc-script-block\"><h3>\' + esc(title) + \'</h3><pre>\' + esc(body) + \'</pre>\'\n      + (note ? \'<p class=\"calc-script-note\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\n  }\n  function table(title, head, rows, note) {\n    var h = \'<tr>\' + head.map(function (c) { return \'<th>\' + esc(c) + \'</th>\'; }).join(\'\') + \'</tr>\';\n    var b = rows.map(function (r) {\n      return \'<tr>\' + r.map(function (c) { return \'<td>\' + esc(c) + \'</td>\'; }).join(\'\') + \'</tr>\';\n    }).join(\'\');\n    return \'<div class=\"calc-script-block\"><h3>\' + esc(title) + \'</h3>\'\n      + \'<div class=\"calc-script-scroll\"><table class=\"calc-script-table\">\' + h + b + \'</table></div>\'\n      + (note ? \'<p class=\"calc-script-note\">\' + esc(note) + \'</p>\' : \'\') + \'</div>\';\n  }\n  function resolve(raw, map, fallback) {\n    var n = String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\');\n    if (Object.prototype.hasOwnProperty.call(map, raw)) return map[raw];\n    var keys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });\n    for (var i = 0; i < keys.length; i++) {\n      var k = keys[i].toLowerCase().replace(/[^a-z0-9]/g, \'\');\n      if (k && n.indexOf(k) >= 0) return map[keys[i]];\n    }\n    return fallback;\n  }\n  var BASES = \'TCAG\';\n  var AA_ORDER = \'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG\';\n  function aaOf(codon) {\n    var i1 = BASES.indexOf(codon.charAt(0)), i2 = BASES.indexOf(codon.charAt(1)),\n        i3 = BASES.indexOf(codon.charAt(2));\n    if (i1 < 0 || i2 < 0 || i3 < 0) return null;\n    return AA_ORDER.charAt(i1 * 16 + i2 * 4 + i3);\n  }\n\n  function norm(raw) { return String(raw || \'\').toLowerCase().replace(/[^a-z0-9]/g, \'\'); }\n  /*\n   * The panel stores a choice as a uid derived from the option *label*, so every\n   * genotype label for one locus begins with the same letters (\"e-e-...\", \"b-b-...\").\n   * Reading the letters back out would always pick the first option, so each locus\n   * is read from the words that actually distinguish its options.\n   */\n  function pickE(raw) {\n    var n = norm(raw);\n    if (n.indexOf(\'noblack\') >= 0) return \'ee\';\n    if (n.indexOf(\'carries\') >= 0) return \'Ee\';\n    return \'EE\';\n  }\n  function pickK(raw) {\n    var n = norm(raw);\n    if (n.indexOf(\'brindle\') >= 0) return \'KBR\';\n    if (n.indexOf(\'solid\') >= 0) return \'KB\';\n    return \'ky\';\n  }\n  function pickB(raw) {\n    var n = norm(raw);\n    if (n.indexOf(\'chocolate\') >= 0 || n.indexOf(\'brownbrown\') >= 0) return \'bb\';\n    if (n.indexOf(\'carries\') >= 0) return \'Bb\';\n    return \'BB\';\n  }\n  function pickD(raw) {\n    var n = norm(raw);\n    if (n.indexOf(\'diluted\') >= 0 || n.indexOf(\'lilac\') >= 0) return \'dd\';\n    if (n.indexOf(\'carries\') >= 0) return \'Dd\';\n    return \'DD\';\n  }\n  var E_MAP = { ee: \'red/yellow\', Ee: \'has black\', EE: \'has black\' };\n  var B_MAP = { BB: \'black\', Bb: \'black (carries brown)\', bb: \'brown\' };\n  var D_MAP = { DD: \'full\', Dd: \'full (carries dilute)\', dd: \'dilute\' };\n  function colourOf(e, k, b, d) {\n    // e/e: no black pigment at all — the other loci cannot put colour back\n    if (e === \'ee\') {\n      return d === \'dd\' ? \'cream (dilute red)\' : \'red / yellow / golden\';\n    }\n    // K^B makes the dog solid black whatever A would otherwise do\n    if (k === \'KB\') {\n      if (d === \'dd\') return \'blue (dilute black)\';\n      return \'solid black\';\n    }\n    if (k === \'KBR\') {\n      if (d === \'dd\') return \'blue brindle (dilute brindle)\';\n      return \'brindle\';\n    }\n    // k^y/k^y: the A locus shows; we do not model A, so both pigment states appear\n    if (b === \'bb\') {\n      if (d === \'dd\') return \'lilac / isabella (dilute chocolate)\';\n      if (k === \'ky\') return \'chocolate (or agouti-patterned brown)\';\n      return \'chocolate\';\n    }\n    if (d === \'dd\') return k === \'ky\' ? \'blue, or blue agouti\' : \'blue\';\n    return k === \'ky\' ? \'black, or the agouti pattern (sable, tan points)\' : \'black\';\n  }\n  omni.onResult([\'e_locus\', \'k_locus\', \'b_locus\', \'d_locus\', \'ticking\'], function (ctx) {\n    var e = pickE(ctx.getRawInput(\'e_locus\'));\n    var k = pickK(ctx.getRawInput(\'k_locus\'));\n    var b = pickB(ctx.getRawInput(\'b_locus\'));\n    var d = pickD(ctx.getRawInput(\'d_locus\'));\n    var ticking = /true|yes|1/i.test(String(ctx.getRawInput(\'ticking\') || \'\'));\n    var colour = colourOf(e, k, b, d);\n    if (ticking) colour += \', with ticking\';\n    ctx.exportValue(\'loci\', 4);\n    var rows = [\n      [\'E (extension)\', e, E_MAP[e] || \'\'],\n      [\'K (dominant black)\', k === \'KB\' ? \'K^B\' : (k === \'KBR\' ? \'K^br\' : \'k^y/k^y\'), k === \'KB\' ? \'solid black\' : (k === \'KBR\' ? \'brindle\' : \'lets agouti show\')],\n      [\'B (brown)\', b, B_MAP[b] || \'\'],\n      [\'D (dilution)\', d, D_MAP[d] || \'\'],\n      [\'T (ticking)\', ticking ? \'T/-\' : \'t/t\', ticking ? \'flecks on white\' : \'no ticking\']\n    ];\n    var html = block(\'Predicted coat colour\',\n      \'Genotype   E: \' + e + \'   K: \' + (k === \'KB\' ? \'K^B\' : (k === \'KBR\' ? \'K^br\' : \'k^y/k^y\'))\n      + \'   B: \' + b + \'   D: \' + d + \'\\nPhenotype  \' + colour,\n      e === \'ee\'\n        ? \'With e/e no black pigment is made, so the B, K and D loci cannot darken the dog — this is why two yellow Labradors never produce a black puppy.\'\n        : \'The loci act in the order E then K then A then B then D; the first one that decides the outcome wins.\');\n    html += table(\'What each locus is doing\', [\'Locus\', \'Genotype\', \'Effect\'], rows);\n    ctx.addHtml(html);\n  });', NULL, 0, 1, 1, '2026-10-29 14:08:51', '2026-10-29 14:08:51'),
(209, 'in-vivo-formulation', 'biology', 'In Vivo Formulation Calculator', 'In Vivo Formulation Calculator', 'In Vivo Formulation Calculator — Formula & Results', 'Work out the dosing volume, the amount of compound to weigh out and the dilution you need before an in vivo study. Free in vivo formulation calculator: enter', 'Work out the dosing volume, the amount of compound to weigh out and the dilution you need before an in vivo study. It returns volume per animal, dose volume per kg, compound for the cohort and minimum stock concentration, and the panel shows all of them at once.\n\nGive the dose in mg/kg, the animal\'s weight and the stock concentration, and the page returns the volume to inject or dose orally, the total compound for the whole cohort, and whether the dose sits inside a sensible volume-to-bodyweight limit. Every result is derived from the boxes you fill in, so changing one input updates the whole panel at once. Units are stated on every box and in every result, so a figure copied out of a protocol, a datasheet or a chart can be entered without converting it first.', '[{\"title\":\"The formula behind the In Vivo Formulation\",\"html\":\"<p>V (µL) = dose (mg/kg) × body weight (g) ÷ 1000 ÷ stock (mg/mL) × 1000;  compound = dose × weight ÷ 1000 × animals</p>\\n<figure class=\\\"calc-figure\\\"><img src=\\\"/uploads/biology/in-vivo-formulation.svg\\\" width=\\\"720\\\" height=\\\"300\\\" loading=\\\"lazy\\\" alt=\\\"Animated diagram: In Vivo Formulation Calculator — Volume per dose against the usual route limits\\\" title=\\\"In Vivo Formulation Calculator\\\"><figcaption>Volume per dose against the usual route limits</figcaption></figure>\\n<table><caption>The symbols in the formula</caption><thead><tr><th>Symbol</th><th>What it stands for</th><th>Unit</th></tr></thead><tbody><tr><td><code>dose</code></td><td>milligrams of compound per kilogram of animal</td><td>mg/kg</td></tr><tr><td><code>weight</code></td><td>body weight of one animal</td><td>g</td></tr><tr><td><code>stock</code></td><td>concentration of the solution you dose from</td><td>mg/mL</td></tr><tr><td><code>V</code></td><td>volume given to one animal</td><td>µL</td></tr></tbody></table>\"},{\"title\":\"How do I use the In Vivo Formulation?\",\"html\":\"<p>The form asks only for what the formula needs — nothing is optional decoration.</p>\\n<ol><li>Enter the target dose and the average weight of the animals in the cohort.</li><li>Enter the stock concentration you have, or plan to make.</li><li>Compare the volume per animal with the route\'s limit: oral and subcutaneous doses are usually capped around 10 mL/kg, intravenous around 5 mL/kg.</li><li>Weigh out the compound the page reports, plus a little for losses — the figure is the theoretical minimum for the cohort.</li></ol>\"},{\"title\":\"A worked example\",\"html\":\"<p>Take the default values the page opens with: dose of <strong>10</strong> mg/kg, body weight of <strong>25</strong> g, number of animals of <strong>10</strong>, stock concentration of <strong>5</strong> mg/mL, maximum volume per dose of <strong>10</strong> mL/kg.</p>\\n<p>Substituting them into the formula gives volume per animal of <strong>50</strong> µL, dose volume per kg of <strong>2</strong> mL/kg, compound for the cohort of <strong>2.5</strong> mg, minimum stock concentration of <strong>1</strong> mg/mL, dilution factor to that stock of <strong>5</strong> ×.</p>\\n<p>The arithmetic is the page\'s own: change one box and the result moves by the amount the formula implies, which is the quickest way to convince yourself the tool is honest.</p>\"},{\"title\":\"What does the result mean?\",\"html\":\"<p>A raw figure only means something next to the bands it is normally judged against. Here is the scale that goes with this one:</p>\\n<table><caption>How to read the result</caption><thead><tr><th>Result</th><th>Band</th><th>What it means</th></tr></thead><tbody><tr><td>≤ 5 mL/kg</td><td><strong>Comfortable</strong></td><td>fine for every common route including IV bolus</td></tr><tr><td>5 – 10 mL/kg</td><td><strong>Acceptable</strong></td><td>usual ceiling for oral gavage and subcutaneous dosing</td></tr><tr><td>10 – 20 mL/kg</td><td><strong>High</strong></td><td>only for oral dosing, and it disturbs fluid balance</td></tr><tr><td>above 20 mL/kg</td><td><strong>Too high</strong></td><td>raise the stock concentration instead of the volume</td></tr></tbody></table>\\n<ul><li><p>The volume limit is a physiological constraint, not a convenience: a 25 g mouse given 1 mL has received 40 mL/kg, which is a fluid load large enough to change absorption and sometimes the result.</p></li><li><p>If the required volume exceeds the limit, the answer is a more concentrated stock, not a larger injection. The page reports the weakest stock that still fits, and how far your current stock could be diluted toward it.</p></li><li><p>The compound figure assumes no dead volume, no priming of lines and no spillage. In practice prepare 10–20 % extra, and more for a long study or a suspension.</p></li><li><p>For a suspension rather than a solution, dose by mass and vortex immediately before each dose — a settled suspension is the commonest cause of a variable exposure.</p></li></ul>\"},{\"title\":\"What are the common mistakes?\",\"html\":\"<p>The arithmetic is simple; the inputs are where things go wrong. The usual culprits:</p><ul><li>Mixing grams and milligrams: a 25 g mouse is 0.025 kg, and using 25 kg under-doses by 1000×.</li><li>Ignoring the volume limit and dosing 20 mL/kg because the arithmetic was easier.</li><li>Forgetting the vehicle-only control group when calculating how much compound to weigh out.</li><li>Assuming the stock concentration is exact: check the salt form and the purity, because both change the amount of free compound.</li></ul>\"},{\"title\":\"Calculators that go with this one\",\"html\":\"<p>If you need the rest of the working, these cover the adjacent quantities:</p><p><a href=\\\"/biology/dilution-calculator-c1v1\\\">Dilution C1V1</a>. <a href=\\\"/biology/mass-molarity-conversion\\\">Mass ↔ molarity</a>. <a href=\\\"/health/pediatric-dose\\\">Paediatric dose</a>. <a href=\\\"/biology/serial-dilution-planner\\\">Serial dilution planner</a>.</p>\"}]', '[{\"q\":\"How do I convert a mg/kg dose to a volume?\",\"a\":\"Multiply the dose by the animal\'s weight in kilograms to get the mass of compound, then divide by the stock concentration. For a 25 g mouse at 10 mg/kg from a 5 mg/mL stock that is 0.25 mg ÷ 5 mg/mL = 50 µL.\"},{\"q\":\"What is a safe injection volume for a mouse?\",\"a\":\"Roughly 10 mL/kg for oral and subcutaneous routes and 5 mL/kg for intravenous — about 250 µL and 125 µL for a 25 g mouse. Above that you are dosing fluid as much as compound.\"},{\"q\":\"Should I weigh out extra compound?\",\"a\":\"Yes. The page gives the theoretical minimum for the cohort; add 10–20 % for dead volume and losses, and more if the compound is a suspension or the study runs for days.\"},{\"q\":\"Does body weight matter that much?\",\"a\":\"It scales the dose linearly, so a cohort that gains 10 % during a study receives 10 % more compound at the same volume. Re-weigh weekly and adjust the volume, not the concentration.\"},{\"q\":\"What does the In Vivo Formulation actually calculate?\",\"a\":\"It returns volume per animal, dose volume per kg, compound for the cohort and minimum stock concentration. Each one is derived by the formula on this page, so you can check any figure by hand.\"},{\"q\":\"Do I have to fill in every box?\",\"a\":\"Fill in the ones you know. The result boxes are computed from them, so you never enter a value the formula can derive — and if you change an input, every result updates with it.\"}]', '[{\"key\":\"dose\",\"label\":\"Dose\",\"type\":\"number\",\"default\":\"10\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Milligrams of compound per kilogram of animal\",\"prefix\":\"\",\"suffix\":\"mg/kg\",\"options\":[],\"output\":false},{\"key\":\"weight\",\"label\":\"Body weight\",\"type\":\"number\",\"default\":\"25\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Average weight of the animals\",\"prefix\":\"\",\"suffix\":\"g\",\"options\":[],\"output\":false},{\"key\":\"animals\",\"label\":\"Number of animals\",\"type\":\"number\",\"default\":\"10\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Doses to prepare\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":false},{\"key\":\"stock\",\"label\":\"Stock concentration\",\"type\":\"number\",\"default\":\"5\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"The solution you have or will make\",\"prefix\":\"\",\"suffix\":\"mg/mL\",\"options\":[],\"output\":false},{\"key\":\"max_vol\",\"label\":\"Maximum volume per dose\",\"type\":\"number\",\"default\":\"10\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"5 mL/kg oral, 10 mL/kg IP are common limits\",\"prefix\":\"\",\"suffix\":\"mL/kg\",\"options\":[],\"output\":false},{\"key\":\"volume\",\"label\":\"Volume per animal\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"µL\",\"options\":[],\"output\":true},{\"key\":\"volume_kg\",\"label\":\"Dose volume per kg\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"mL/kg\",\"options\":[],\"output\":true},{\"key\":\"compound\",\"label\":\"Compound for the cohort\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Weigh this much out\",\"prefix\":\"\",\"suffix\":\"mg\",\"options\":[],\"output\":true},{\"key\":\"stock_needed\",\"label\":\"Minimum stock concentration\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"To stay inside the volume limit\",\"prefix\":\"\",\"suffix\":\"mg/mL\",\"options\":[],\"output\":true},{\"key\":\"dilution\",\"label\":\"Dilution factor to that stock\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"×\",\"options\":[],\"output\":true}]', '[{\"formula\":\"Dose\",\"directions\":[{\"l\":\"volume\",\"f\":\"dose*weight/1000/stock*1000\"},{\"l\":\"volume_kg\",\"f\":\"dose*weight/1000/stock*1000/weight\"},{\"l\":\"compound\",\"f\":\"dose*weight/1000*animals\"},{\"l\":\"stock_needed\",\"f\":\"dose/max_vol\"},{\"l\":\"dilution\",\"f\":\"stock/(dose/max_vol)\"}]}]', '{\"path\":\"/biology/in-vivo-formulation\",\"slug\":\"in-vivo-formulation\",\"cat\":\"biology\",\"name\":\"In Vivo Formulation Calculator\",\"title\":\"In Vivo Formulation Calculator — Formula & Results\",\"desc\":\"Work out the dosing volume, the amount of compound to weigh out and the dilution you need before an in vivo study. Free in vivo formulation calculator: enter\",\"authors\":[],\"reviewers\":[],\"updated\":\"2026-10-29\",\"rate\":0,\"groups\":[{\"uid\":\"custom-in-vivo-formulation\",\"title\":\"\",\"desc\":\"\",\"m\":[[\"FR2\",[[{\"t\":\"v\",\"n\":\"dose\",\"l\":\"Dose\",\"h\":\"Milligrams of compound per kilogram of animal\",\"suf\":\"mg/kg\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"weight\",\"l\":\"Body weight\",\"h\":\"Average weight of the animals\",\"suf\":\"g\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"animals\",\"l\":\"Number of animals\",\"h\":\"Doses to prepare\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"stock\",\"l\":\"Stock concentration\",\"h\":\"The solution you have or will make\",\"suf\":\"mg/mL\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"max_vol\",\"l\":\"Maximum volume per dose\",\"h\":\"5 mL/kg oral, 10 mL/kg IP are common limits\",\"suf\":\"mL/kg\",\"vt\":\"numerical\"}],[{\"t\":\"v\",\"n\":\"volume\",\"l\":\"Volume per animal\",\"suf\":\"µL\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"volume_kg\",\"l\":\"Dose volume per kg\",\"suf\":\"mL/kg\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"compound\",\"l\":\"Compound for the cohort\",\"h\":\"Weigh this much out\",\"suf\":\"mg\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"stock_needed\",\"l\":\"Minimum stock concentration\",\"h\":\"To stay inside the volume limit\",\"suf\":\"mg/mL\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"dilution\",\"l\":\"Dilution factor to that stock\",\"suf\":\"×\",\"oo\":1,\"vt\":\"numerical\"}]]]]}],\"vars\":{\"dose\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"10\",\"c\":null}]},\"weight\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"25\",\"c\":null}]},\"animals\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"10\",\"c\":null}]},\"stock\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"5\",\"c\":null}]},\"max_vol\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"10\",\"c\":null}]},\"volume\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"volume_kg\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"compound\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"stock_needed\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"dilution\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]}},\"datasets\":[],\"eq\":[{\"formula\":\"Dose\",\"var\":[{\"l\":\"volume\",\"f\":\"dose*weight/1000/stock*1000\",\"r\":[\"dose\",\"weight\",\"stock\"]},{\"l\":\"volume_kg\",\"f\":\"dose*weight/1000/stock*1000/weight\",\"r\":[\"dose\",\"weight\",\"stock\"]},{\"l\":\"compound\",\"f\":\"dose*weight/1000*animals\",\"r\":[\"dose\",\"weight\",\"animals\"]},{\"l\":\"stock_needed\",\"f\":\"dose/max_vol\",\"r\":[\"dose\",\"max_vol\"]},{\"l\":\"dilution\",\"f\":\"stock/(dose/max_vol)\",\"r\":[\"stock\",\"dose\",\"max_vol\"]}]}],\"js\":null,\"needsJs\":false}', 'dropper', '', 'published', 0, 1000, 0, NULL, NULL, 0, 1, 1, '2026-10-29 14:08:52', '2026-10-29 14:08:52'),
(210, 'dna-percentage', 'biology', 'DNA Percentage Calculator', 'DNA Percentage Calculator', 'DNA Percentage Calculator — Formula & Results', 'The DNA percentage of a genome is the share of its bases that code for protein. Free dna percentage calculator: enter your values and get coding percentage, n', 'The DNA percentage of a genome is the share of its bases that code for protein. It returns coding percentage, non-coding share, gene density and bases per gene, and the panel shows all of them at once.\n\nGive the genome size and either the coding bases or a gene count with a mean gene length, and the page returns the coding percentage, the non-coding share, the gene density in genes per megabase and the mean bases per gene — the numbers that decide whether a genome is compact or mostly intergenic. Press Calculate and the results appear in the grey boxes; after the first press they keep up with every edit, so there is no page to reload. Units are stated on every box and in every result, so a figure copied out of a protocol, a datasheet or a chart can be entered without converting it first.', '[{\"title\":\"The formula behind the DNA Percentage\",\"html\":\"<p>coding % = coding bases ÷ genome size × 100;  gene density = genes ÷ genome size (Mb);  bases per gene = genome (bp) ÷ genes</p>\\n<figure class=\\\"calc-figure\\\"><img src=\\\"/uploads/biology/dna-percentage.svg\\\" width=\\\"720\\\" height=\\\"300\\\" loading=\\\"lazy\\\" alt=\\\"Animated diagram: DNA Percentage Calculator — Coding share of four genomes\\\" title=\\\"DNA Percentage Calculator\\\"><figcaption>Coding share of four genomes</figcaption></figure>\\n<table><caption>The symbols in the formula</caption><thead><tr><th>Symbol</th><th>What it stands for</th><th>Unit</th></tr></thead><tbody><tr><td><code>genome</code></td><td>haploid genome size</td><td>Mb</td></tr><tr><td><code>coding</code></td><td>total length of coding sequence</td><td>Mb</td></tr><tr><td><code>genes</code></td><td>number of protein-coding genes</td><td>—</td></tr><tr><td><code>gene density</code></td><td>how tightly genes are packed</td><td>genes/Mb</td></tr></tbody></table>\"},{\"title\":\"How do I use the DNA Percentage?\",\"html\":\"<p>Every input sits in the same order the formula is written, so the page reads like the equation.</p>\\n<ol><li>Enter the genome size in megabases — one copy, not the diploid total.</li><li>Enter the coding bases: the sum of all coding exons, which is what a genome annotation gives you as the total CDS length.</li><li>Add the gene count if you want gene density and bases per gene; leave it as it is to skip those two lines.</li><li>Compare the coding percentage across organisms: it is the single clearest number for how much of a genome is doing something.</li></ol>\"},{\"title\":\"A worked example\",\"html\":\"<p>Take the default values the page opens with: genome size of <strong>3,000</strong> Mb, coding bases of <strong>90</strong> Mb, gene count of <strong>20,000</strong>.</p>\\n<p>Substituting them into the formula gives coding percentage of <strong>3</strong>%, non-coding share of <strong>97</strong>%, gene density of <strong>6.67</strong> genes/Mb, bases per gene of <strong>150,000</strong> bp, coding bases per gene of <strong>4,500</strong> bp.</p>\\n<p>Those numbers come from the same solver the page runs in your browser, not from an illustration, so typing different inputs moves the answer exactly as the arithmetic says.</p>\"},{\"title\":\"What does the result mean?\",\"html\":\"<p>The number on its own is not a judgement. These are the bands most often used when the result is quoted in a paper, a report or a label:</p>\\n<table><caption>How to read the result</caption><thead><tr><th>Result</th><th>Band</th><th>What it means</th></tr></thead><tbody><tr><td>above 70 %</td><td><strong>Compact</strong></td><td>bacterial and archaeal genomes, and viral genomes</td></tr><tr><td>30 – 70 %</td><td><strong>Dense</strong></td><td>small eukaryotes such as yeast and some fungi</td></tr><tr><td>10 – 30 %</td><td><strong>Typical eukaryote</strong></td><td>invertebrates and many plants</td></tr><tr><td>1 – 10 %</td><td><strong>Sparse</strong></td><td>vertebrates, including the human 1.5 %</td></tr><tr><td>below 1 %</td><td><strong>Very sparse</strong></td><td>large plant and amphibian genomes dominated by repeats</td></tr></tbody></table>\\n<ul><li><p>The human figure is about 1.5 % coding and roughly 39 % in introns; the rest is intergenic sequence, much of it repetitive. A genome can be 50× larger than another with barely more genes — the difference is mostly repeats.</p></li><li><p>Coding percentage is not the same as exon percentage: exons include untranslated regions, so exon totals run higher than coding sequence totals.</p></li><li><p>Gene density and mean gene length move in opposite directions across taxa: compact genomes have short genes packed closely, which is why the bases-per-gene figure is worth reading next to the density.</p></li><li><p>Genome size here is haploid. A diploid cell contains twice this, which matters if you are converting to mass of DNA per cell.</p></li></ul>\"},{\"title\":\"What are the common mistakes?\",\"html\":\"<p>These are the errors that account for almost every wrong answer people bring to this calculator:</p><ul><li>Using the diploid genome size and then comparing with published haploid percentages.</li><li>Entering the number of exons instead of the coding length.</li><li>Comparing coding percentages between an annotation that counts only reviewed genes and one that includes predicted open reading frames.</li><li>Assuming non-coding means non-functional: promoters, enhancers and non-coding RNA all live in the non-coding share.</li></ul>\"},{\"title\":\"Calculators that go with this one\",\"html\":\"<p>This tool answers one step of the question. The neighbouring steps have their own pages:</p><p><a href=\\\"/biology/coding-capacity-of-dna\\\">Coding capacity of DNA</a>. <a href=\\\"/biology/genome-copy-number\\\">Genome copy number</a>. <a href=\\\"/biology/dna-concentration\\\">DNA concentration</a>. <a href=\\\"/biology/gc-content-calculator\\\">GC content</a>.</p>\"}]', '[{\"q\":\"What percentage of the human genome is coding?\",\"a\":\"About 1.5 % — roughly 30 Mb of coding sequence in a 3 000 Mb haploid genome. Adding untranslated regions brings the exonic total to a few percent, and introns take about 39 %.\"},{\"q\":\"Why do some genomes have almost no non-coding DNA?\",\"a\":\"Because selection against carrying extra DNA is strong in fast-growing cells with large population sizes, which is the usual explanation for bacterial genome compaction.\"},{\"q\":\"Is coding percentage the same as gene density?\",\"a\":\"No. Gene density counts genes per megabase and says how packed the genes are; coding percentage measures how much of the sequence is coding. A genome can be gene-dense and still have a low coding percentage if its genes are mostly introns.\"},{\"q\":\"Can I use this for a single gene or contig?\",\"a\":\"Yes, with small numbers: a 2 000 bp gene with 1 500 bp of coding sequence is 75 % coding. The same formula works at any scale.\"},{\"q\":\"What does the DNA Percentage actually calculate?\",\"a\":\"It returns coding percentage, non-coding share, gene density and bases per gene. Each one is derived by the formula on this page, so you can check any figure by hand.\"},{\"q\":\"Do I have to fill in every box?\",\"a\":\"Fill in the ones you know. The result boxes are computed from them, so you never enter a value the formula can derive — and if you change an input, every result updates with it.\"}]', '[{\"key\":\"genome\",\"label\":\"Genome size\",\"type\":\"number\",\"default\":\"3000\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"3 000 Mb is a mammalian genome\",\"prefix\":\"\",\"suffix\":\"Mb\",\"options\":[],\"output\":false},{\"key\":\"coding\",\"label\":\"Coding bases\",\"type\":\"number\",\"default\":\"90\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Sum of all coding exons\",\"prefix\":\"\",\"suffix\":\"Mb\",\"options\":[],\"output\":false},{\"key\":\"genes\",\"label\":\"Gene count\",\"type\":\"number\",\"default\":\"20000\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"Optional — used for gene density\",\"prefix\":\"\",\"suffix\":\"\",\"options\":[],\"output\":false},{\"key\":\"coding_pct\",\"label\":\"Coding percentage\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"%\",\"options\":[],\"output\":true},{\"key\":\"noncoding_pct\",\"label\":\"Non-coding share\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"%\",\"options\":[],\"output\":true},{\"key\":\"gene_density\",\"label\":\"Gene density\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"genes/Mb\",\"options\":[],\"output\":true},{\"key\":\"bases_per_gene\",\"label\":\"Bases per gene\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"bp\",\"options\":[],\"output\":true},{\"key\":\"coding_per_gene\",\"label\":\"Coding bases per gene\",\"type\":\"number\",\"default\":\"\",\"unit_group\":\"\",\"unit_default\":\"\",\"help\":\"\",\"prefix\":\"\",\"suffix\":\"bp\",\"options\":[],\"output\":true}]', '[{\"formula\":\"Genome\",\"directions\":[{\"l\":\"coding_pct\",\"f\":\"coding/genome*100\"},{\"l\":\"noncoding_pct\",\"f\":\"100-coding/genome*100\"},{\"l\":\"gene_density\",\"f\":\"genes/genome\"},{\"l\":\"bases_per_gene\",\"f\":\"genome*1000000/genes\"},{\"l\":\"coding_per_gene\",\"f\":\"coding*1000000/genes\"}]}]', '{\"path\":\"/biology/dna-percentage\",\"slug\":\"dna-percentage\",\"cat\":\"biology\",\"name\":\"DNA Percentage Calculator\",\"title\":\"DNA Percentage Calculator — Formula & Results\",\"desc\":\"The DNA percentage of a genome is the share of its bases that code for protein. Free dna percentage calculator: enter your values and get coding percentage, n\",\"authors\":[],\"reviewers\":[],\"updated\":\"2026-10-29\",\"rate\":0,\"groups\":[{\"uid\":\"custom-dna-percentage\",\"title\":\"\",\"desc\":\"\",\"m\":[[\"FR2\",[[{\"t\":\"v\",\"n\":\"genome\",\"l\":\"Genome size\",\"h\":\"3 000 Mb is a mammalian genome\",\"suf\":\"Mb\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"coding\",\"l\":\"Coding bases\",\"h\":\"Sum of all coding exons\",\"suf\":\"Mb\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"genes\",\"l\":\"Gene count\",\"h\":\"Optional — used for gene density\",\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"coding_pct\",\"l\":\"Coding percentage\",\"suf\":\"%\",\"oo\":1,\"vt\":\"numerical\"}],[{\"t\":\"v\",\"n\":\"noncoding_pct\",\"l\":\"Non-coding share\",\"suf\":\"%\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"gene_density\",\"l\":\"Gene density\",\"suf\":\"genes/Mb\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"bases_per_gene\",\"l\":\"Bases per gene\",\"suf\":\"bp\",\"oo\":1,\"vt\":\"numerical\"},{\"t\":\"v\",\"n\":\"coding_per_gene\",\"l\":\"Coding bases per gene\",\"suf\":\"bp\",\"oo\":1,\"vt\":\"numerical\"}]]]]}],\"vars\":{\"genome\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"3000\",\"c\":null}]},\"coding\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"90\",\"c\":null}]},\"genes\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"],\"dfl\":[{\"v\":\"20000\",\"c\":null}]},\"coding_pct\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"noncoding_pct\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"gene_density\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"bases_per_gene\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]},\"coding_per_gene\":{\"type\":\"numerical\",\"rnd\":[\"omni\",\"0.0001\"]}},\"datasets\":[],\"eq\":[{\"formula\":\"Genome\",\"var\":[{\"l\":\"coding_pct\",\"f\":\"coding/genome*100\",\"r\":[\"coding\",\"genome\"]},{\"l\":\"noncoding_pct\",\"f\":\"100-coding/genome*100\",\"r\":[\"coding\",\"genome\"]},{\"l\":\"gene_density\",\"f\":\"genes/genome\",\"r\":[\"genes\",\"genome\"]},{\"l\":\"bases_per_gene\",\"f\":\"genome*1000000/genes\",\"r\":[\"genome\",\"genes\"]},{\"l\":\"coding_per_gene\",\"f\":\"coding*1000000/genes\",\"r\":[\"coding\",\"genes\"]}]}],\"js\":null,\"needsJs\":false}', 'dna', '', 'published', 0, 1000, 0, NULL, NULL, 0, 1, 1, '2026-10-29 14:08:52', '2026-10-29 14:08:52');

