-- ------------------------------------------------------------ message_notes
DROP TABLE IF EXISTS `message_notes`;
CREATE TABLE `message_notes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `message_id` int(10) unsigned NOT NULL,
  `user_id` int(10) unsigned DEFAULT NULL,
  `note` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_notes_message` (`message_id`),
  CONSTRAINT `fk_notes_message` FOREIGN KEY (`message_id`) REFERENCES `messages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ messages
DROP TABLE IF EXISTS `messages`;
CREATE TABLE `messages` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(190) NOT NULL DEFAULT '',
  `email` varchar(190) NOT NULL DEFAULT '',
  `phone` varchar(60) NOT NULL DEFAULT '',
  `subject` varchar(190) NOT NULL DEFAULT '',
  `body` mediumtext DEFAULT NULL,
  `extra` longtext DEFAULT NULL,
  `status` enum('unread','read','resolved','spam') NOT NULL DEFAULT 'unread',
  `ip` varchar(45) NOT NULL DEFAULT '',
  `user_agent` varchar(255) NOT NULL DEFAULT '',
  `referer` varchar(255) NOT NULL DEFAULT '',
  `mail_status` enum('pending','sent','failed','disabled') NOT NULL DEFAULT 'pending',
  `mail_error` varchar(500) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `read_at` datetime DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_messages_status` (`status`,`created_at`),
  KEY `idx_messages_email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ page_views
DROP TABLE IF EXISTS `page_views`;
CREATE TABLE `page_views` (
  `path` varchar(190) NOT NULL,
  `day` date NOT NULL,
  `hits` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`path`,`day`),
  KEY `idx_views_day` (`day`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ pages
DROP TABLE IF EXISTS `pages`;
CREATE TABLE `pages` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(190) NOT NULL,
  `title` varchar(190) NOT NULL,
  `excerpt` varchar(320) NOT NULL DEFAULT '',
  `content` longtext DEFAULT NULL,
  `template` enum('default','contact','wide','faq') NOT NULL DEFAULT 'default',
  `status` enum('published','draft') NOT NULL DEFAULT 'draft',
  `meta_title` varchar(190) NOT NULL DEFAULT '',
  `meta_description` varchar(320) NOT NULL DEFAULT '',
  `canonical_url` varchar(255) NOT NULL DEFAULT '',
  `noindex` tinyint(1) NOT NULL DEFAULT 0,
  `show_in_header` tinyint(1) NOT NULL DEFAULT 0,
  `show_in_footer` tinyint(1) NOT NULL DEFAULT 0,
  `author_id` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pages_slug` (`slug`),
  KEY `idx_pages_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `pages` (`id`, `slug`, `title`, `excerpt`, `content`, `template`, `status`, `meta_title`, `meta_description`, `canonical_url`, `noindex`, `show_in_header`, `show_in_footer`, `author_id`, `created_at`, `updated_at`) VALUES
(1, 'about', 'About this calculator site', 'What this site is, how the calculators are built, and what it does with your data (spoiler: it keeps it on your device).', '<p>This site is a library of free online calculators. Type a number, get an answer, and see the formula that produced it. No account, no paywall, no \"unlock the result\" step.</p>\n<h2>How a calculator is built</h2>\n<p>Every calculator is described by the relationships between its inputs. Those relationships — the equations — are what the page runs on, both on the server and again in your browser when you press Calculate. Where a problem needs more than arithmetic (a table lookup, an iterative solve, a piecewise rule), that logic is written out as a step-by-step method instead of being hidden behind a black box.</p>\n<h2>How the maths is checked</h2>\n<p>Each calculator is tested against worked examples with results that are stated independently of the code: the answer is computed by hand, then the page has to reproduce it. A calculator that disagrees is a bug and is fixed rather than annotated.</p>\n<h2>What happens to your numbers</h2>\n<p>Calculations run in your browser and on this server while the page is being drawn. We do not store what you type, we do not build profiles, and we do not sell anything to anyone. The only data we keep is what you deliberately send us, such as a message through the contact form.</p>\n<h2>Advertising</h2>\n<p>If advertising is enabled on this deployment, it is configured by the site owner and disclosed in the privacy policy. Ads never change a result.</p>', 'default', 'published', 'About this calculator site', 'How these free calculators are built, how the maths is checked, and why every page shows its formula.', '', 0, 0, 1, 1, '2026-10-29 14:08:39', '2026-10-29 14:08:39'),
(2, 'privacy', 'Privacy policy', 'What this site collects, why, and how to have it removed.', '<p>This policy explains what this site does with data. It applies to the calculator pages, the blog and the contact form.</p>\n<h2>Calculator pages</h2>\n<p>Values you type into a calculator are used to compute your result. They are not written to a database and they are not attached to you in any way. When you reload the page, they are gone.</p>\n<h2>Server logs</h2>\n<p>The web server records requests in the standard way: IP address, timestamp, requested URL and browser identifier. Logs exist to keep the service running and to spot abuse, and they are rotated on a short schedule.</p>\n<h2>Aggregate page counts</h2>\n<p>To know which calculators are worth improving, the site keeps a daily counter per page — a number, not a person. It stores the page path and the date. There is no visitor identifier, no cookie and no cross-site tracking.</p>\n<h2>Contact form</h2>\n<p>When you send a message we store the name, email address and text you submit, plus the IP address used to send it, so we can answer you and block spam. Messages are kept until the question is settled and then deleted on request. Message content is never used for marketing.</p>\n<h2>Cookies</h2>\n<p>The public site sets no tracking cookies. The admin area sets one session cookie, which is required to stay signed in and is not used for anything else.</p>\n<h2>Third parties</h2>\n<p>If the site owner enables an analytics provider or advertising network, that provider may set its own cookies and is named in the consent banner the owner enables. This deployment runs its own counters and nothing else unless the owner changes that.</p>\n<h2>Your rights</h2>\n<p>Write to the contact address on the contact page to ask what we hold about you, to correct it, or to have it deleted. You do not need to give a reason.</p>', 'default', 'published', 'Privacy policy', 'The data this calculator site collects, how long it is kept, and how to request deletion.', '', 0, 0, 1, 1, '2026-10-29 14:08:39', '2026-10-29 14:08:39'),
(3, 'terms', 'Terms of use', 'The short version: use the calculators freely, check anything important, and do not abuse the service.', '<p>By using this site you agree to these terms. They are deliberately short.</p>\n<h2>The calculators are a tool, not advice</h2>\n<p>Results are produced by the formulas documented on each page. They are general-purpose: they do not know your tax residency, your lender\'s fees, your medical history or your local building code. For decisions with money, health or safety consequences, confirm the result with a qualified professional or with the primary source (the tax office, the lender, the clinician, the code).</p>\n<h2>Accuracy and availability</h2>\n<p>We test every calculator and fix disagreements between the documented formula and the result. We cannot promise the site will never be wrong or never be down, and we do not accept liability for decisions taken on the strength of a result alone.</p>\n<h2>Acceptable use</h2>\n<p>Do not scrape the site at a rate that degrades it for other people, do not use the contact form to send unsolicited advertising, and do not attempt to reach the administration area or other users\' data.</p>\n<h2>Content</h2>\n<p>The explanatory text on this site was written for it. You may quote a passage with a link back; you may not republish whole articles. Calculator definitions and interface patterns are provided for study and reuse by their respective authors.</p>\n<h2>Changes</h2>\n<p>These terms may change as the site does. The current version is always this page.</p>', 'default', 'published', 'Terms of use', 'The terms that apply to using these free calculators and the content on this site.', '', 0, 0, 1, 1, '2026-10-29 14:08:39', '2026-10-29 14:08:39'),
(4, 'disclaimer', 'Disclaimer', 'Financial, medical and legal results are estimates — here is exactly what that means.', '<p>Every calculator on this site is an estimate built from a documented formula. This page says, plainly, where the limits are.</p>\n<h2>Money</h2>\n<p>Loan, mortgage, investment and tax calculators reproduce standard formulas. Real statements differ: interest accrues on your lender\'s schedule, fees are charged in ways the formula cannot see, and tax rules change and depend on where you live. Treat the output as a planning figure and compare it with an official statement before committing to anything.</p>\n<h2>Health</h2>\n<p>Health calculators (BMI, dosage, pregnancy dates, risk scores) are educational. They use population-level formulas, not your individual clinical picture. They are not a diagnosis, a prescription or a substitute for a clinician who has examined you.</p>\n<h2>Engineering, construction and safety</h2>\n<p>Material, structural and electrical calculators give estimates from simplified models. Loads, tolerances and codes vary by jurisdiction and by product. Anything that bears weight, conducts current or holds back water needs a qualified professional and the manufacturer\'s data.</p>\n<h2>No professional relationship</h2>\n<p>Using this site does not create a professional relationship of any kind. No result here constitutes financial, legal, medical or engineering advice.</p>', 'default', 'published', 'Disclaimer', 'What the results on this site are and are not: estimates that need checking against a professional or a primary source.', '', 0, 0, 1, 1, '2026-10-29 14:08:39', '2026-10-29 14:08:39'),
(5, 'faq', 'Frequently asked questions', 'How the calculators work, why a field is blank, and what to do when a result looks wrong.', '<h2>Why is one field blank?</h2>\n<p>Most calculators work out whichever value you leave empty. Fill in the ones you know, leave the one you want, and the result appears. If every field is filled, the page still shows the result for the equation you selected.</p>\n<h2>Do the units matter?</h2>\n<p>Yes, and they are handled for you. The chip next to each field changes the unit without changing the number you typed — 5 inches stays 5 as a number and becomes 12.7 cm internally. Mixed units in one form are fine.</p>\n<h2>Why does the result differ from another site?</h2>\n<p>Usually because of a different assumption: a different day count in a date calculation, a different rounding step, or a different definition of the same word (a \"month\" of 30 days rather than a calendar month). Each page states its assumptions.</p>\n<h2>Can I link to a result?</h2>\n<p>Yes. The address bar holds the whole form state, so a copied URL opens the page with the same values and the same answer.</p>\n<h2>How do I report a wrong answer?</h2>\n<p>Use the contact form, include the calculator\'s name, the values you entered and the answer you expected. A wrong result is a bug and gets fixed.</p>', 'faq', 'published', 'Frequently asked questions', 'Answers about units, blank fields, accuracy, privacy and reporting a wrong result on this calculator site.', '', 0, 0, 1, 1, '2026-10-29 14:08:39', '2026-10-29 14:08:39'),
(6, 'contact', 'Contact', 'Report a bug, ask for a calculator, or say hello.', '<p>Bug reports get priority. If a result looks wrong, include the calculator name, the values you entered and the answer you expected — that is usually enough to reproduce it.</p>\n<p>Requests for new calculators are read and, when they fit the library, built. A note on what you were trying to work out helps more than a one-line \"please add X\".</p>', 'contact', 'published', 'Contact', 'How to reach the people behind this calculator site: bug reports, calculator requests and press.', '', 0, 0, 1, 1, '2026-10-29 14:08:39', '2026-10-29 14:08:39');

